"use strict";exports.id=8082,exports.ids=[8082],exports.modules={98082:(a,b,c)=>{c.d(b,{jN:()=>e,l6:()=>g,N9:()=>f,B0:()=>h});let d=[{slug:"como-calcular-preco-de-servico",title:"Como calcular o pre\xe7o de um servi\xe7o sem cobrar barato demais",metaTitle:"Como calcular o pre\xe7o de um servi\xe7o (com exemplos)",metaDescription:"Aprenda o passo a passo para precificar um servi\xe7o corretamente: custos diretos, valor do seu tempo e margem de lucro, com exemplos pr\xe1ticos.",excerpt:"Cobrar barato demais \xe9 o motivo mais comum de prestadores de servi\xe7o trabalharem muito e sobrarem pouco no fim do m\xeas. Veja o passo a passo para chegar num pre\xe7o justo — pra voc\xea e pro cliente.",pillar:"precificacao",coverImage:"/blog/covers/como-calcular-preco-de-servico.jpg",coverImageAlt:"M\xe3os usando calculadora ao lado de uma nota fiscal",publishedAt:"2026-01-12",updatedAt:"2026-01-12",readingTimeMinutes:7,sections:[{type:"paragraph",text:"Quem presta servi\xe7o — seja pintura, consultoria, design, aulas particulares ou qualquer outra atividade — em algum momento se pega diante da mesma pergunta: quanto eu cobro? Cobrar pouco \xe9 o erro mais comum, e o mais caro: voc\xea trabalha bastante, fatura razo\xe1vel, mas no fim do m\xeas sobra pouco ou nada. A boa not\xedcia \xe9 que precificar n\xe3o precisa ser um chute. Existe uma l\xf3gica simples por tr\xe1s de um pre\xe7o justo, que qualquer pessoa consegue aplicar sem precisar de curso de administra\xe7\xe3o."},{type:"heading",level:2,text:"Por que cobrar 'na intui\xe7\xe3o' quase sempre sai caro",id:"por-que-intuicao-sai-caro"},{type:"paragraph",text:"\xc9 comum precificar olhando pro concorrente ou perguntando 'quanto que t\xe1 bom?'. O problema \xe9 que isso ignora a coisa mais importante: o que aquele servi\xe7o custa PRA VOC\xca fazer. Um pre\xe7o que parece 'justo' pelo mercado pode estar bem abaixo do que cobre seus gastos e ainda deixe alguma sobra. Com o tempo, isso vira uma rotina de trabalhar muito para ganhar pouco — e \xe9 exatamente o padr\xe3o que leva gente boa a desistir do pr\xf3prio neg\xf3cio."},{type:"heading",level:2,text:"Os tr\xeas n\xfameros que formam qualquer pre\xe7o",id:"tres-numeros-do-preco"},{type:"paragraph",text:"Todo pre\xe7o de servi\xe7o, por mais simples ou complexo que pare\xe7a, nasce de tr\xeas n\xfameros somados:"},{type:"list",items:["Custos diretos — tudo que voc\xea gasta pra entregar aquele servi\xe7o espec\xedfico: materiais, insumos, deslocamento, terceiros contratados.","Valor do seu tempo e trabalho — quanto vale a sua dedica\xe7\xe3o, sua t\xe9cnica e sua experi\xeancia naquele servi\xe7o.","Margem de lucro — o percentual que sobra de verdade, depois de cobrir tudo, pra reinvestir no neg\xf3cio ou simplesmente for o seu ganho."]},{type:"paragraph",text:"A f\xf3rmula mais simples e mais usada por pequenos neg\xf3cios \xe9 a margem sobre o pre\xe7o final: voc\xea soma custos diretos com o valor do seu tempo, e divide pelo complemento da margem que voc\xea quer (100% menos a margem). Parece mais complicado escrito do que \xe9 na pr\xe1tica — veja o exemplo abaixo."},{type:"callout",title:"Exemplo pr\xe1tico",text:"Um servi\xe7o custa R$150 em materiais e o seu tempo nele vale R$300. Custo total: R$450. Se voc\xea quer 30% de margem sobre o pre\xe7o final, o c\xe1lculo \xe9 R$450 \xf7 (1 − 0,30) = R$642,86. Ou seja: cobrando R$642,86, sobram exatos R$192,86 de lucro depois de pagar tudo — os 30% que voc\xea definiu, nem um centavo a menos."},{type:"heading",level:2,text:"Como estimar o valor do seu tempo",id:"valor-do-tempo"},{type:"paragraph",text:"Esse costuma ser o n\xfamero mais dif\xedcil de definir, porque n\xe3o \xe9 uma nota fiscal — \xe9 uma decis\xe3o sua. Uma forma pr\xe1tica de chegar nele: pense em quanto voc\xea gostaria de ganhar por m\xeas trabalhando nesse tipo de servi\xe7o, divida por quantos dias voc\xea trabalha e por quantas horas \xfateis tem em cada dia. Isso te d\xe1 um valor-hora de refer\xeancia, que voc\xea multiplica pelo tempo real que aquele servi\xe7o espec\xedfico exige — incluindo prepara\xe7\xe3o, execu\xe7\xe3o e finaliza\xe7\xe3o, n\xe3o s\xf3 a 'parte vis\xedvel' do trabalho."},{type:"paragraph",text:"Um erro comum aqui \xe9 contar s\xf3 a hora de execu\xe7\xe3o e esquecer o tempo de planejamento, deslocamento, ajustes e atendimento ao cliente. Se um servi\xe7o leva 2 horas de execu\xe7\xe3o mas exige 1 hora de prepara\xe7\xe3o antes, o tempo real \xe9 3 horas — e \xe9 isso que deve entrar na conta."},{type:"heading",level:2,text:"Qual margem de lucro \xe9 razo\xe1vel cobrar",id:"margem-de-lucro-razoavel"},{type:"paragraph",text:"N\xe3o existe um n\xfamero m\xe1gico universal, mas prestadores de servi\xe7o costumam trabalhar numa faixa entre 20% e 50% de margem, dependendo de quanto risco, exclusividade ou complexidade o servi\xe7o envolve. Servi\xe7os mais padronizados e recorrentes tendem pra faixa mais baixa (20%-30%); trabalhos personalizados, urgentes ou que exigem habilidade rara podem sustentar margens mais altas (40%-50%) sem espantar o cliente — porque o valor percebido tamb\xe9m \xe9 maior."},{type:"list",items:["20%-25%: servi\xe7os de rotina, alta repeti\xe7\xe3o, baixo risco.","30%-35%: ponto de partida seguro para a maioria dos prestadores de servi\xe7o.","40%-50%: trabalho personalizado, complexo ou com prazo apertado."]},{type:"heading",level:2,text:"O erro de confundir pre\xe7o baixo com competitividade",id:"preco-baixo-nao-e-competitividade"},{type:"paragraph",text:"Baixar o pre\xe7o parece a forma mais r\xe1pida de fechar mais clientes, mas na pr\xe1tica costuma sair caro: al\xe9m de reduzir sua margem, um pre\xe7o muito abaixo do mercado gera desconfian\xe7a ('por que t\xe3o barato?') e atrai o tipo de cliente mais propenso a pedir desconto, cancelar ou disputar cada detalhe. Um pre\xe7o calculado com base nos seus custos reais — n\xe3o no medo de perder a venda — tende a atrair clientes que valorizam mais o trabalho e negociam menos."},{type:"heading",level:2,text:"Calcule o seu pre\xe7o agora",id:"calcule-agora"},{type:"paragraph",text:"Se voc\xea quer aplicar essa conta no seu pr\xf3prio servi\xe7o sem fazer a matem\xe1tica na m\xe3o, a Calculadora de Precifica\xe7\xe3o da Tropa j\xe1 faz isso por voc\xea: voc\xea informa seus custos diretos, o valor do seu tempo e a margem que quer, e ela calcula o pre\xe7o sugerido, o lucro em reais e o pre\xe7o por unidade — em segundos, e de gra\xe7a."}],faq:[{question:"Qual a diferen\xe7a entre margem de lucro e markup?",answer:"Margem de lucro \xe9 calculada sobre o pre\xe7o final de venda (quanto do pre\xe7o \xe9 lucro). Markup \xe9 calculado sobre o custo (quanto voc\xea soma em cima do custo). Os dois chegam a pre\xe7os diferentes para a mesma porcentagem — por isso \xe9 importante saber qual dos dois voc\xea est\xe1 usando. A margem sobre o pre\xe7o final \xe9 mais direta para garantir exatamente o percentual de lucro que voc\xea quer."},{question:"Devo cobrar por hora ou por projeto fechado?",answer:"Depende do tipo de trabalho. Servi\xe7os com escopo bem definido (uma pintura, um contrato, uma pe\xe7a gr\xe1fica) costumam funcionar melhor com pre\xe7o fechado, porque o cliente sabe exatamente quanto vai pagar. Servi\xe7os com escopo vari\xe1vel ou imprevis\xedvel (consultoria cont\xednua, suporte t\xe9cnico) costumam funcionar melhor cobrados por hora."},{question:"E se o cliente disser que o pre\xe7o est\xe1 caro?",answer:"Antes de baixar o pre\xe7o, vale entender se o cliente est\xe1 comparando com um servi\xe7o realmente equivalente. Se o seu pre\xe7o j\xe1 reflete seus custos reais e uma margem razo\xe1vel, baix\xe1-lo sem motivo tende a comprometer sua margem sem necessariamente fechar mais vendas. Uma alternativa \xe9 ajustar o escopo (entregar menos) em vez de manter o escopo e cobrar menos."}],relatedTool:{title:"Calculadora de Precifica\xe7\xe3o",href:"/ferramentas/calculadora-precificacao",description:"Informe seus custos, seu tempo e a margem que voc\xea quer — o pre\xe7o sugerido aparece na hora."},relatedSlugs:["cobrar-por-hora-ou-por-projeto","o-que-nao-pode-faltar-contrato-prestacao-servico","o-que-e-das-mei-como-pagar"]},{slug:"o-que-e-das-mei-como-pagar",title:"O que \xe9 o DAS do MEI e como pagar em dia",metaTitle:"DAS do MEI: o que \xe9, quanto custa e como pagar",metaDescription:"Entenda o que \xe9 o DAS do MEI, o que ele cobre, quanto custa por m\xeas e o que acontece se voc\xea atrasar o pagamento.",excerpt:"O DAS \xe9 a guia mensal que todo MEI precisa pagar — e a d\xfavida mais comum de quem est\xe1 come\xe7ando. Veja o que ele cobre, quanto custa e o que fazer se atrasar.",pillar:"mei",coverImage:"/blog/covers/o-que-e-das-mei-como-pagar.jpg",coverImageAlt:"Mulher usando o celular para organizar as finan\xe7as em casa",publishedAt:"2026-01-15",updatedAt:"2026-01-15",readingTimeMinutes:6,sections:[{type:"paragraph",text:"Se voc\xea \xe9 MEI ou est\xe1 pensando em abrir um, uma das primeiras siglas que vai aparecer no seu caminho \xe9 o DAS. \xc9 o boleto mensal que mant\xe9m o CNPJ regularizado — e entender como ele funciona evita boa parte dos problemas que MEIs enfrentam com a Receita Federal."},{type:"heading",level:2,text:"O que \xe9 o DAS",id:"o-que-e-o-das"},{type:"paragraph",text:"DAS significa Documento de Arrecada\xe7\xe3o do Simples Nacional. \xc9 a guia \xfanica de pagamento mensal do MEI, que re\xfane em um s\xf3 boleto todos os tributos que, numa empresa maior, seriam pagos separadamente: INSS, ICMS (para quem vende produtos) ou ISS (para quem presta servi\xe7o). Em vez de lidar com v\xe1rias guias diferentes, o MEI paga um valor fixo mensal, simplificando bastante a rotina fiscal."},{type:"heading",level:2,text:"Quanto custa o DAS por m\xeas",id:"quanto-custa-o-das"},{type:"paragraph",text:"O valor do DAS \xe9 fixo e reajustado todo ano com base no sal\xe1rio m\xednimo vigente — por isso n\xe3o muda dependendo de quanto o MEI faturou naquele m\xeas espec\xedfico. O valor varia de acordo com o tipo de atividade:"},{type:"list",items:["Com\xe9rcio ou ind\xfastria: contribui\xe7\xe3o de INSS + ICMS.","Presta\xe7\xe3o de servi\xe7os: contribui\xe7\xe3o de INSS + ISS.","Com\xe9rcio e servi\xe7os juntos: contribui\xe7\xe3o de INSS + ICMS + ISS."]},{type:"paragraph",text:"Como o valor exato muda todo ano (\xe9 reajustado junto com o sal\xe1rio m\xednimo), o mais seguro \xe9 sempre conferir o valor atualizado direto no Portal do Simples Nacional ou no aplicativo MEI, em vez de confiar em um n\xfamero fixo publicado h\xe1 tempos em algum lugar da internet."},{type:"heading",level:2,text:"O que o DAS cobre exatamente",id:"o-que-o-das-cobre"},{type:"paragraph",text:"O pagamento do DAS garante dois benef\xedcios importantes al\xe9m de manter o CNPJ regular:"},{type:"list",items:["Aposentadoria e benef\xedcios do INSS — o MEI que paga o DAS em dia contribui para a previd\xeancia, tendo direito a aposentadoria por idade, aux\xedlio-doen\xe7a, sal\xe1rio-maternidade e pens\xe3o por morte para dependentes.","Regularidade fiscal do CNPJ — sem o DAS em dia, o CNPJ pode ser bloqueado, impedindo emiss\xe3o de nota fiscal e outras opera\xe7\xf5es."]},{type:"heading",level:2,text:"At\xe9 quando pagar o DAS",id:"ate-quando-pagar"},{type:"paragraph",text:"O vencimento do DAS \xe9 sempre at\xe9 o dia 20 de cada m\xeas, referente ao m\xeas anterior. Se o dia 20 cair em fim de semana ou feriado, o vencimento passa automaticamente para o pr\xf3ximo dia \xfatil. A guia pode ser gerada e paga pelo Portal do Simples Nacional, pelo aplicativo MEI ou diretamente pelo internet banking, usando o c\xf3digo de barras."},{type:"heading",level:2,text:"O que acontece se o MEI atrasar o DAS",id:"o-que-acontece-se-atrasar"},{type:"paragraph",text:"Atrasar o DAS n\xe3o cancela o CNPJ automaticamente, mas traz consequ\xeancias reais:"},{type:"list",items:["Juros e multa sobre o valor em atraso, calculados dia a dia.","Perda tempor\xe1ria dos direitos previdenci\xe1rios enquanto a guia estiver em aberto.","Ac\xfamulo de pend\xeancias que, se ultrapassar um certo per\xedodo sem regulariza\xe7\xe3o, pode levar ao cancelamento do MEI de of\xedcio pela Receita Federal."]},{type:"paragraph",text:"A boa not\xedcia \xe9 que d\xe1 pra regularizar: \xe9 poss\xedvel emitir o DAS em atraso (j\xe1 com os juros e multa calculados automaticamente) direto pelo Portal do Simples Nacional, a qualquer momento. Quanto antes regularizar, menor o valor acumulado."},{type:"heading",level:2,text:"Como n\xe3o esquecer de pagar todo m\xeas",id:"como-nao-esquecer"},{type:"paragraph",text:"Como o valor n\xe3o muda de m\xeas para m\xeas, a forma mais simples de nunca atrasar \xe9 configurar um d\xe9bito autom\xe1tico pelo aplicativo MEI ou pelo internet banking, ou simplesmente colocar um lembrete fixo alguns dias antes do vencimento. Ter um contador acompanhando sua situa\xe7\xe3o tamb\xe9m ajuda — al\xe9m de cuidar do DAS, ele avisa sobre outras obriga\xe7\xf5es que o MEI \xe0s vezes esquece, como a Declara\xe7\xe3o Anual (DASN-SIMEI)."}],faq:[{question:"O DAS muda de valor se eu faturar mais em um m\xeas?",answer:"N\xe3o. O DAS do MEI \xe9 um valor fixo mensal, definido pela atividade (com\xe9rcio, servi\xe7o ou os dois) e reajustado uma vez por ano com base no sal\xe1rio m\xednimo — independentemente de quanto voc\xea faturou naquele m\xeas espec\xedfico."},{question:"Posso parcelar o DAS atrasado?",answer:"Sim, \xe9 poss\xedvel parcelar d\xe9bitos de DAS em atraso diretamente pelo Portal do Simples Nacional, dentro das regras vigentes de parcelamento para o MEI. O ideal \xe9 regularizar o quanto antes para reduzir juros e evitar o cancelamento do CNPJ por inadimpl\xeancia."},{question:"O que acontece se eu n\xe3o pagar o DAS nunca?",answer:"Al\xe9m dos juros e multas acumulados, o MEI que fica muito tempo sem pagar o DAS pode ter o CNPJ cancelado de of\xedcio pela Receita Federal, perdendo a regularidade para emitir notas fiscais e os direitos previdenci\xe1rios vinculados \xe0s contribui\xe7\xf5es."}],relatedTool:{title:"Abrir meu MEI",href:"/abrir-cnpj",description:"Tire d\xfavidas sobre o seu MEI ou sobre trocar de contador com quem entende do assunto."},relatedSlugs:["como-abrir-mei-passo-a-passo","como-emitir-nota-fiscal-mei","mei-pode-ter-funcionario"]},{slug:"diferenca-demissao-sem-justa-causa-pedido-acordo",title:"Demiss\xe3o sem justa causa, pedido de demiss\xe3o ou acordo: qual a diferen\xe7a",metaTitle:"Demiss\xe3o sem justa causa vs. pedido vs. acordo: diferen\xe7as",metaDescription:"Entenda a diferen\xe7a entre demiss\xe3o sem justa causa, pedido de demiss\xe3o e rescis\xe3o por acordo — e o que cada uma muda no valor final da rescis\xe3o.",excerpt:"O tipo de desligamento muda completamente o valor que a pessoa recebe (ou paga) na rescis\xe3o. Veja a diferen\xe7a entre as tr\xeas formas mais comuns de encerrar um contrato CLT.",pillar:"rescisao",coverImage:"/blog/covers/diferenca-demissao-sem-justa-causa-pedido-acordo.jpg",coverImageAlt:"Profissional organizando pertences em uma caixa no escrit\xf3rio",publishedAt:"2026-01-18",updatedAt:"2026-01-18",readingTimeMinutes:6,sections:[{type:"paragraph",text:"Encerrar um contrato de trabalho CLT parece simples at\xe9 a hora de calcular o que \xe9 devido — porque o valor final muda bastante dependendo de quem tomou a iniciativa e de como. As tr\xeas formas mais comuns de desligamento sem justa causa por parte do funcion\xe1rio s\xe3o bem diferentes entre si, e confundir uma com a outra \xe9 a maior fonte de erro (e de expectativa frustrada) na hora do acerto final."},{type:"heading",level:2,text:"Demiss\xe3o sem justa causa",id:"demissao-sem-justa-causa"},{type:"paragraph",text:"\xc9 quando a empresa decide encerrar o contrato, sem que o funcion\xe1rio tenha cometido nenhuma falta grave. \xc9 o cen\xe1rio mais completo em termos de direitos: o funcion\xe1rio recebe saldo de sal\xe1rio, 13\xba proporcional, f\xe9rias proporcionais mais um ter\xe7o, aviso pr\xe9vio (trabalhado ou indenizado) e a multa de 40% sobre o saldo do FGTS, al\xe9m de ter direito a sacar o FGTS e solicitar o seguro-desemprego, se atender aos requisitos."},{type:"heading",level:2,text:"Pedido de demiss\xe3o",id:"pedido-de-demissao"},{type:"paragraph",text:"\xc9 quando o pr\xf3prio funcion\xe1rio decide sair. Nesse caso, os direitos s\xe3o bem mais limitados: recebe saldo de sal\xe1rio, 13\xba proporcional e f\xe9rias proporcionais mais um ter\xe7o — mas n\xe3o tem direito \xe0 multa de 40% do FGTS, n\xe3o pode sacar o saldo do FGTS (salvo exce\xe7\xf5es espec\xedficas) e n\xe3o tem direito ao seguro-desemprego. Al\xe9m disso, se o funcion\xe1rio n\xe3o cumprir o aviso pr\xe9vio de 30 dias (ou n\xe3o for dispensado dele pela empresa), o valor correspondente pode ser descontado das verbas rescis\xf3rias."},{type:"heading",level:2,text:"Rescis\xe3o por acordo (distrato)",id:"rescisao-por-acordo"},{type:"paragraph",text:"\xc9 um meio-termo criado pela reforma trabalhista: empresa e funcion\xe1rio concordam em encerrar o contrato juntos. Nesse formato, o funcion\xe1rio recebe metade do aviso pr\xe9vio indenizado (se n\xe3o for trabalhado) e metade da multa do FGTS (20% em vez de 40%). Tamb\xe9m pode movimentar at\xe9 80% do saldo do FGTS, mas n\xe3o tem direito ao seguro-desemprego. \xc9 uma op\xe7\xe3o \xfatil quando as duas partes j\xe1 concordam que o v\xednculo deve terminar, evitando desgaste."},{type:"heading",level:2,text:"Comparando as tr\xeas, lado a lado",id:"comparando-lado-a-lado"},{type:"table",headers:["Verba","Sem justa causa","Pedido de demiss\xe3o","Acordo"],rows:[["Saldo de sal\xe1rio","Sim","Sim","Sim"],["13\xba e f\xe9rias proporcionais","Sim","Sim","Sim"],["Multa do FGTS","40%","N\xe3o tem","20%"],["Saque do FGTS","Integral","N\xe3o (regra geral)","At\xe9 80%"],["Seguro-desemprego","Sim, se eleg\xedvel","N\xe3o","N\xe3o"],["Aviso pr\xe9vio indenizado","Integral","S\xf3 se dispensado pela empresa","Metade"]]},{type:"heading",level:2,text:"Por que isso muda tanto o valor final",id:"por-que-muda-o-valor"},{type:"paragraph",text:"A multa do FGTS costuma ser a maior verba de toda a rescis\xe3o, ent\xe3o a diferen\xe7a entre 40%, 20% e zero j\xe1 explica boa parte da dist\xe2ncia entre os tr\xeas cen\xe1rios. Some a isso o aviso pr\xe9vio (integral, parcial ou nenhum) e o acesso ou n\xe3o ao seguro-desemprego, e fica claro por que a mesma pessoa, com o mesmo sal\xe1rio e tempo de casa, pode receber valores bem diferentes dependendo apenas de quem tomou a decis\xe3o de encerrar o contrato — e como."},{type:"heading",level:2,text:"Simule o valor da sua rescis\xe3o",id:"simule-o-valor"},{type:"paragraph",text:"Em vez de tentar calcular tudo isso na m\xe3o, o Simulador de Rescis\xe3o da Tropa j\xe1 aplica essas regras automaticamente: voc\xea escolhe o tipo de desligamento e informa sal\xe1rio, datas e saldo do FGTS, e recebe uma estimativa das principais verbas — incluindo o custo estimado para a empresa."}],faq:[{question:"Quem pede demiss\xe3o tem direito a algum aviso pr\xe9vio?",answer:"Quem pede demiss\xe3o precisa cumprir 30 dias de aviso pr\xe9vio trabalhado, a n\xe3o ser que a empresa dispense esse cumprimento. Se o funcion\xe1rio simplesmente n\xe3o comparecer, a empresa pode descontar o valor correspondente das verbas rescis\xf3rias."},{question:"A rescis\xe3o por acordo pode ser proposta pelo funcion\xe1rio?",answer:"Sim. A rescis\xe3o por acordo pode partir tanto da empresa quanto do funcion\xe1rio — o ponto central \xe9 que as duas partes precisam concordar formalmente com essa modalidade para que ela seja v\xe1lida."},{question:"Justa causa entra nessa compara\xe7\xe3o?",answer:"N\xe3o \xe9 um desses tr\xeas casos. Na demiss\xe3o por justa causa, o funcion\xe1rio perde a maior parte dos direitos rescis\xf3rios (inclusive a multa do FGTS e o saque) por ter cometido uma falta grave prevista em lei, como comprovada indisciplina ou m\xe1 conduta."}],relatedTool:{title:"Simulador de Rescis\xe3o",href:"/ferramentas/simulador-rescisao",description:"Escolha o tipo de desligamento e veja uma estimativa das principais verbas em segundos."},relatedSlugs:["o-que-e-aviso-previo-como-funciona","quanto-custa-funcionario-clt","como-calcular-preco-de-servico"]},{slug:"quanto-custa-funcionario-clt",title:"Quanto custa contratar um funcion\xe1rio CLT (al\xe9m do sal\xe1rio)",metaTitle:"Quanto custa um funcion\xe1rio CLT de verdade",metaDescription:"O sal\xe1rio \xe9 s\xf3 uma parte do custo de contratar CLT. Veja tudo que entra na conta: FGTS, 13\xba, f\xe9rias, encargos e benef\xedcios.",excerpt:"Quem nunca contratou costuma se surpreender: o custo real de um funcion\xe1rio CLT costuma ficar bem acima do sal\xe1rio combinado. Veja o que entra nessa conta.",pillar:"contratacao",coverImage:"/blog/covers/quanto-custa-funcionario-clt.jpg",coverImageAlt:"Aperto de m\xe3o entre empres\xe1rio e candidata em entrevista de emprego",publishedAt:"2026-01-20",updatedAt:"2026-01-20",readingTimeMinutes:7,sections:[{type:"paragraph",text:"Quando o neg\xf3cio come\xe7a a crescer e chega a hora de contratar a primeira pessoa, \xe9 comum planejar o or\xe7amento olhando s\xf3 para o sal\xe1rio combinado. O problema \xe9 que o sal\xe1rio \xe9 apenas uma fatia do custo real — e quem n\xe3o considera o resto acaba levando um susto no fim do primeiro m\xeas. Entender essa conta antes de contratar evita comprometer o caixa da empresa."},{type:"heading",level:2,text:"O sal\xe1rio \xe9 s\xf3 o ponto de partida",id:"salario-e-ponto-de-partida"},{type:"paragraph",text:"Contratar CLT significa assumir uma s\xe9rie de obriga\xe7\xf5es previstas em lei, al\xe9m do pr\xf3prio sal\xe1rio. Cada uma delas aumenta um pouco o custo mensal e, no final, o custo real de manter um funcion\xe1rio costuma ficar entre 1,5 e 2 vezes o sal\xe1rio bruto — dependendo do regime tribut\xe1rio da empresa e dos benef\xedcios oferecidos."},{type:"heading",level:2,text:"O que entra na conta, item por item",id:"o-que-entra-na-conta"},{type:"list",items:["FGTS — 8% do sal\xe1rio, depositado todo m\xeas numa conta vinculada ao funcion\xe1rio.","13\xba sal\xe1rio — equivalente a mais um sal\xe1rio por ano, provisionado m\xeas a m\xeas (1/12 do sal\xe1rio por m\xeas trabalhado).","F\xe9rias + 1/3 — um sal\xe1rio extra a cada 12 meses trabalhados, tamb\xe9m provisionado mensalmente.","Encargos patronais — variam conforme o regime tribut\xe1rio da empresa (no Simples Nacional Anexo IV, por exemplo, incidem por fora do DAS).","Vale-transporte — obrigat\xf3rio quando solicitado pelo funcion\xe1rio, com desconto de at\xe9 6% do sal\xe1rio dele.","Vale-alimenta\xe7\xe3o ou refei\xe7\xe3o — n\xe3o \xe9 obrigat\xf3rio por lei, mas \xe9 praticamente padr\xe3o de mercado hoje.","Plano de sa\xfade e outros benef\xedcios — opcionais, mas comuns em vagas mais competitivas."]},{type:"callout",title:"Exemplo pr\xe1tico",text:"Um funcion\xe1rio com sal\xe1rio de R$2.500, vale-transporte de R$220, vale-alimenta\xe7\xe3o de R$550 e sem plano de sa\xfade, numa empresa do Simples Nacional regime regular (sem encargo patronal adicional), custa aproximadamente R$3.995 por m\xeas — cerca de 1,6 vezes o sal\xe1rio. Em uma empresa do Anexo IV ou do Lucro Presumido, com encargos patronais de 28,8%, esse custo sobe para mais de R$5.000."},{type:"heading",level:2,text:"Por que o regime tribut\xe1rio muda tanto essa conta",id:"regime-tributario-muda-conta"},{type:"paragraph",text:"Empresas do Simples Nacional em regime regular n\xe3o pagam encargo patronal adicional sobre a folha — o INSS patronal j\xe1 est\xe1 inclu\xeddo no DAS. J\xe1 as empresas enquadradas no Anexo IV do Simples (algumas atividades de servi\xe7o, como constru\xe7\xe3o civil e alguns tipos de consultoria) e as do Lucro Presumido ou Real pagam a parte patronal do INSS por fora, o que costuma adicionar entre 26% e 30% sobre o sal\xe1rio e as provis\xf5es. Saber em qual enquadramento a empresa est\xe1 \xe9 essencial antes de fechar a conta de quanto vai custar contratar."},{type:"heading",level:2,text:"Erros comuns na hora de calcular o custo de contrata\xe7\xe3o",id:"erros-comuns"},{type:"list",items:["Esquecer o 13\xba e as f\xe9rias na provis\xe3o mensal — eles n\xe3o aparecem na folha do m\xeas, mas precisam estar reservados.","N\xe3o verificar o pr\xf3prio regime tribut\xe1rio antes de estimar os encargos.","Contar o vale-transporte pelo valor cheio, sem considerar o desconto de at\xe9 6% do sal\xe1rio do funcion\xe1rio.","Comparar apenas o sal\xe1rio com o custo de um freelancer ou PJ, sem incluir os encargos na compara\xe7\xe3o."]},{type:"heading",level:2,text:"Simule o custo antes de contratar",id:"simule-antes-de-contratar"},{type:"paragraph",text:"O Simulador de Contrata\xe7\xe3o da Tropa j\xe1 calcula essa conta inteira: voc\xea informa o sal\xe1rio, o regime da empresa e os benef\xedcios, e ele mostra o custo m\xe9dio mensal, o custo anual e o detalhamento de cada item — em segundos, sem precisar montar planilha."}],faq:[{question:"O custo de um funcion\xe1rio CLT \xe9 sempre o dobro do sal\xe1rio?",answer:"N\xe3o necessariamente — costuma ficar entre 1,5 e 2 vezes o sal\xe1rio, dependendo do regime tribut\xe1rio da empresa e dos benef\xedcios oferecidos. Empresas do Simples Nacional regular tendem para a faixa mais baixa; empresas do Anexo IV, Presumido ou Real tendem para a faixa mais alta."},{question:"MEI pode contratar funcion\xe1rio CLT?",answer:"Sim, o MEI pode ter um \xfanico funcion\xe1rio registrado, recebendo at\xe9 um sal\xe1rio m\xednimo ou o piso da categoria. Contratar mais de um funcion\xe1rio exige migrar para outro enquadramento, como ME do Simples Nacional."},{question:"Vale-transporte \xe9 obrigat\xf3rio mesmo se o funcion\xe1rio morar perto?",answer:"O vale-transporte \xe9 obrigat\xf3rio sempre que o funcion\xe1rio solicitar, independentemente da dist\xe2ncia — a lei n\xe3o prev\xea exce\xe7\xe3o por proximidade. A empresa pode descontar at\xe9 6% do sal\xe1rio bruto do funcion\xe1rio como participa\xe7\xe3o nesse custo."}],relatedTool:{title:"Simulador de Contrata\xe7\xe3o",href:"/ferramentas/simulador-contratacao",description:"Informe sal\xe1rio, regime e benef\xedcios — veja o custo m\xe9dio mensal e anual em segundos."},relatedSlugs:["mei-pode-ter-funcionario","ferias-clt-como-funciona-o-calculo","como-calcular-decimo-terceiro-salario"]},{slug:"o-que-nao-pode-faltar-contrato-prestacao-servico",title:"O que n\xe3o pode faltar em um contrato de presta\xe7\xe3o de servi\xe7o",metaTitle:"Contrato de presta\xe7\xe3o de servi\xe7o: o que incluir",metaDescription:"Veja as cl\xe1usulas essenciais de um contrato de presta\xe7\xe3o de servi\xe7o para se proteger de calote, retrabalho e mal-entendido com o cliente.",excerpt:"Fechar um servi\xe7o s\xf3 no combinado verbal \xe9 a receita mais comum para dor de cabe\xe7a. Veja o que um contrato de presta\xe7\xe3o de servi\xe7o precisa ter para te proteger de verdade.",pillar:"contratos",coverImage:"/blog/covers/o-que-nao-pode-faltar-contrato-prestacao-servico.jpg",coverImageAlt:"M\xe3o assinando um contrato com caneta sobre a mesa",publishedAt:"2026-01-22",updatedAt:"2026-01-22",readingTimeMinutes:7,sections:[{type:"paragraph",text:"Muita gente s\xf3 sente falta de um contrato quando algo j\xe1 deu errado: o cliente n\xe3o paga, pede altera\xe7\xf5es fora do combinado ou discorda do que foi entregue. Um contrato de presta\xe7\xe3o de servi\xe7o bem feito n\xe3o precisa ser complicado nem caro — mas precisa ter alguns pontos espec\xedficos para realmente proteger as duas partes, n\xe3o s\xf3 existir no papel."},{type:"heading",level:2,text:"Identifica\xe7\xe3o completa das partes",id:"identificacao-das-partes"},{type:"paragraph",text:"Parece \xf3bvio, mas \xe9 o ponto mais esquecido em contratos informais: nome completo (ou raz\xe3o social), CPF ou CNPJ, e endere\xe7o de quem contrata e de quem presta o servi\xe7o. Sem isso, o contrato perde for\xe7a caso seja necess\xe1rio us\xe1-lo formalmente mais tarde."},{type:"heading",level:2,text:"Descri\xe7\xe3o clara do que ser\xe1 feito",id:"descricao-clara-do-servico"},{type:"paragraph",text:"Essa \xe9 a cl\xe1usula que evita mais conflito: descrever com detalhes o que est\xe1 inclu\xeddo no servi\xe7o — e, se poss\xedvel, o que N\xc3O est\xe1 inclu\xeddo. Um contrato vago do tipo 'presta\xe7\xe3o de servi\xe7os de design' abre margem para o cliente pedir revis\xf5es e entregas extras achando que tudo est\xe1 incluso no mesmo valor."},{type:"list",items:["O que exatamente ser\xe1 entregue (quantidade, formato, prazo).","O que est\xe1 fora do escopo (e, se o cliente quiser, como isso \xe9 cobrado \xe0 parte).","Quantas revis\xf5es ou ajustes est\xe3o inclu\xeddos, se for o caso."]},{type:"heading",level:2,text:"Valor, forma e prazo de pagamento",id:"valor-forma-prazo-pagamento"},{type:"paragraph",text:"Al\xe9m do valor total, o contrato deve deixar claro como o pagamento ser\xe1 feito: \xe0 vista, parcelado, com entrada e saldo, ou por etapa. E, principalmente, o que acontece em caso de atraso — se h\xe1 multa, juros, suspens\xe3o do servi\xe7o ou qualquer outra consequ\xeancia combinada."},{type:"heading",level:2,text:"Prazo de entrega e o que acontece se atrasar",id:"prazo-de-entrega"},{type:"paragraph",text:"Vale definir a data (ou o prazo) de entrega, e tamb\xe9m deixar claro se esse prazo depende de alguma a\xe7\xe3o do cliente — como envio de materiais, aprova\xe7\xf5es ou acesso a algum sistema. Sem essa cl\xe1usula, um atraso causado pelo pr\xf3prio cliente pode ser injustamente atribu\xeddo ao prestador."},{type:"heading",level:2,text:"Condi\xe7\xf5es de cancelamento",id:"condicoes-de-cancelamento"},{type:"paragraph",text:"O que acontece se alguma das partes quiser encerrar o contrato antes do fim? Vale prever: se \xe9 preciso avisar com anteced\xeancia, se o que j\xe1 foi feito precisa ser pago, se a entrada \xe9 devolvida, e se h\xe1 alguma multa por cancelamento. Essa cl\xe1usula \xe9 a que mais evita discuss\xe3o quando o servi\xe7o precisa ser interrompido no meio do caminho."},{type:"callout",title:"Dica",text:"Sempre que o servi\xe7o tiver risco de o cliente 'sumir' no meio (comum em projetos de longo prazo ou por etapas), vale detalhar o que j\xe1 foi produzido e \xe9 devido em caso de cancelamento — isso evita ter que provar depois quanto do trabalho j\xe1 estava pronto."},{type:"heading",level:2,text:"Assinatura e validade",id:"assinatura-e-validade"},{type:"paragraph",text:"Um contrato de presta\xe7\xe3o de servi\xe7o n\xe3o precisa de reconhecimento em cart\xf3rio para ter validade jur\xeddica — o que importa \xe9 que as duas partes concordem e assinem (\xe0 m\xe3o ou eletronicamente). Ter testemunhas \xe9 opcional, mas refor\xe7a a seguran\xe7a em casos de valor mais alto."},{type:"heading",level:2,text:"Monte o seu contrato agora",id:"monte-o-seu-contrato"},{type:"paragraph",text:"O Gerador de Contrato da Tropa j\xe1 organiza todas essas cl\xe1usulas por voc\xea: voc\xea responde perguntas simples sobre o servi\xe7o, o pagamento, o prazo e o cancelamento, e recebe um documento pronto para revisar, copiar ou baixar em PDF."}],faq:[{question:"Um contrato de presta\xe7\xe3o de servi\xe7o precisa de advogado?",answer:"N\xe3o \xe9 obrigat\xf3rio. Contratos simples de presta\xe7\xe3o de servi\xe7o podem ser feitos sem advogado, desde que cubram os pontos essenciais (partes, objeto, valor, prazo, cancelamento). Para neg\xf3cios de maior valor ou complexidade jur\xeddica espec\xedfica, vale uma revis\xe3o profissional."},{question:"Contrato assinado digitalmente tem validade?",answer:"Sim. Um contrato assinado eletronicamente (por e-mail, aplicativo de assinatura ou at\xe9 por troca de mensagens com concord\xe2ncia expressa) tem validade jur\xeddica no Brasil, desde que seja poss\xedvel identificar as partes envolvidas."}],relatedTool:{title:"Gerador de Contrato",href:"/ferramentas/gerador-contrato",description:"Monte um contrato de presta\xe7\xe3o de servi\xe7o, venda ou parceria em poucos passos."},relatedSlugs:["o-que-fazer-quando-cliente-nao-paga","como-calcular-preco-de-servico","contrato-verbal-tem-validade"]},{slug:"o-que-fazer-quando-cliente-nao-paga",title:"O que fazer quando o cliente n\xe3o paga pelo servi\xe7o",metaTitle:"Cliente n\xe3o pagou? O que fazer (com e sem contrato)",metaDescription:"Veja os passos pr\xe1ticos para cobrar um cliente que n\xe3o pagou, e como um contrato bem feito evita esse problema desde o in\xedcio.",excerpt:"Prestar o servi\xe7o e n\xe3o receber \xe9 um dos maiores medos de quem trabalha por conta pr\xf3pria. Veja o que fazer se j\xe1 aconteceu — e como evitar da pr\xf3xima vez.",pillar:"contratos",coverImage:"/blog/covers/o-que-fazer-quando-cliente-nao-paga.jpg",coverImageAlt:"Mulher preocupada organizando contas em frente ao notebook",publishedAt:"2026-01-24",updatedAt:"2026-01-24",readingTimeMinutes:6,sections:[{type:"paragraph",text:"N\xe3o receber por um servi\xe7o j\xe1 entregue \xe9 frustrante e, infelizmente, comum. A boa not\xedcia \xe9 que existem passos pr\xe1ticos para tentar resolver a maioria dos casos sem precisar entrar na justi\xe7a — e cl\xe1usulas simples que, inclu\xeddas desde o in\xedcio, reduzem bastante a chance de isso acontecer."},{type:"heading",level:2,text:"Primeiro passo: cobrar de forma formal e educada",id:"cobrar-formal-e-educada"},{type:"paragraph",text:"Antes de qualquer coisa, vale enviar uma cobran\xe7a por escrito — e-mail ou mensagem — deixando registrado o valor devido, a data de vencimento e uma nova data limite para o pagamento. Isso serve tanto para dar ao cliente a chance de resolver de boa-f\xe9 (\xe0s vezes \xe9 s\xf3 esquecimento) quanto para criar um registro caso o caso precise avan\xe7ar."},{type:"heading",level:2,text:"Segundo passo: verificar o que diz o contrato",id:"verificar-o-contrato"},{type:"paragraph",text:"Se existe um contrato assinado, ele j\xe1 deveria prever o que acontece em caso de atraso: multa, juros, ou at\xe9 suspens\xe3o de qualquer servi\xe7o adicional. Refor\xe7ar a cobran\xe7a citando essas cl\xe1usulas espec\xedficas costuma acelerar a resposta, porque deixa claro que a cobran\xe7a tem base formal, n\xe3o \xe9 s\xf3 um pedido informal."},{type:"heading",level:2,text:"Terceiro passo: negociar o pagamento",id:"negociar-o-pagamento"},{type:"paragraph",text:"Nem sempre vale a pena insistir no valor total de uma vez. Propor um parcelamento, mesmo que em duas ou tr\xeas vezes, costuma ter mais chance de sucesso do que manter uma cobran\xe7a r\xedgida que o cliente simplesmente ignora por n\xe3o conseguir pagar tudo de uma vez."},{type:"heading",level:2,text:"Quando considerar as vias formais",id:"vias-formais"},{type:"paragraph",text:"Se a cobran\xe7a amig\xe1vel n\xe3o resolver, existem caminhos formais, dependendo do valor:"},{type:"list",items:["Juizado Especial C\xedvel — para causas de menor valor, sem necessidade de advogado at\xe9 um certo limite, com processo mais r\xe1pido.","Protesto em cart\xf3rio — pode ser feito com um contrato ou nota promiss\xf3ria como t\xedtulo de cr\xe9dito, pressionando o devedor sem precisar de um processo judicial completo.","A\xe7\xe3o de cobran\xe7a comum — para valores mais altos ou casos mais complexos, geralmente com acompanhamento de advogado."]},{type:"heading",level:2,text:"Como evitar isso desde o pr\xf3ximo contrato",id:"como-evitar-desde-o-proximo-contrato"},{type:"paragraph",text:"A forma mais eficaz de lidar com calote \xe9 reduzir a chance de ele acontecer. Algumas pr\xe1ticas simples ajudam bastante:"},{type:"list",items:["Cobrar uma entrada antes de come\xe7ar o servi\xe7o, principalmente em projetos maiores.","Dividir o pagamento por etapas entregues, em vez de cobrar tudo s\xf3 no final.","Deixar por escrito, no contrato, o que acontece em caso de atraso (multa, juros, suspens\xe3o).","Evitar entregar a vers\xe3o final ou os arquivos definitivos antes da confirma\xe7\xe3o do pagamento."]},{type:"callout",title:"Importante",text:"Um contrato n\xe3o impede que o cliente atrase — mas transforma uma discuss\xe3o de 'ele disse, ela disse' em algo com base documentada, o que muda completamente a for\xe7a de uma cobran\xe7a formal ou de um processo, se for necess\xe1rio chegar l\xe1."},{type:"heading",level:2,text:"Proteja o pr\xf3ximo contrato",id:"proteja-o-proximo-contrato"},{type:"paragraph",text:"O Gerador de Contrato da Tropa j\xe1 inclui, entre as op\xe7\xf5es, cl\xe1usulas de forma de pagamento, multa por atraso e condi\xe7\xf5es de cancelamento — prontas para voc\xea incluir no seu pr\xf3ximo contrato sem precisar escrever do zero."}],faq:[{question:"Vale a pena entrar na justi\xe7a por um valor pequeno?",answer:"Para valores menores, o Juizado Especial C\xedvel costuma ser o caminho mais vi\xe1vel: \xe9 mais r\xe1pido, mais barato e, at\xe9 um certo limite de valor, n\xe3o exige advogado. Vale pesar o tempo e o esfor\xe7o envolvidos contra o valor em disputa antes de decidir."},{question:"Um print de conversa serve como prova de que o servi\xe7o foi combinado?",answer:"Pode ajudar como evid\xeancia complementar, mas n\xe3o substitui um contrato formal — \xe9 mais f\xe1cil de contestar e n\xe3o deixa t\xe3o claro todos os termos combinados. Sempre que poss\xedvel, formalizar por contrato (mesmo simples) \xe9 mais seguro."}],relatedTool:{title:"Gerador de Contrato",href:"/ferramentas/gerador-contrato",description:"Monte um contrato com cl\xe1usulas de pagamento, multa por atraso e cancelamento inclu\xeddas."},relatedSlugs:["o-que-nao-pode-faltar-contrato-prestacao-servico","contrato-verbal-tem-validade","como-calcular-preco-de-servico"]},{slug:"como-abrir-mei-passo-a-passo",title:"Como abrir um MEI passo a passo",metaTitle:"Como abrir um MEI: passo a passo completo",metaDescription:"Veja o passo a passo completo para abrir um MEI: documentos necess\xe1rios, como escolher a atividade e o que fazer depois de formalizado.",excerpt:"Abrir um MEI \xe9 gratuito e pode ser feito totalmente online, em poucos minutos. Veja o passo a passo e o que fazer logo depois de formalizar.",pillar:"mei",coverImage:"/blog/covers/como-abrir-mei-passo-a-passo.jpg",coverImageAlt:"Pessoa planejando o neg\xf3cio em um caderno ao lado do notebook",publishedAt:"2026-01-26",updatedAt:"2026-01-26",readingTimeMinutes:6,sections:[{type:"paragraph",text:"O MEI (Microempreendedor Individual) \xe9 a porta de entrada mais simples para formalizar um neg\xf3cio no Brasil. \xc9 gratuito, pode ser feito online e, na maioria dos casos, o CNPJ sai na hora. Mesmo assim, algumas d\xfavidas — qual atividade escolher, o que \xe9 preciso ter em m\xe3os, o que fazer depois — travam quem est\xe1 come\xe7ando. Veja o caminho completo."},{type:"heading",level:2,text:"Quem pode abrir um MEI",id:"quem-pode-abrir-mei"},{type:"paragraph",text:"Para se enquadrar como MEI, \xe9 preciso atender a alguns requisitos: faturar dentro do limite anual estabelecido para a categoria, exercer uma das atividades permitidas para MEI, n\xe3o ser s\xf3cio ou titular de outra empresa, e ter no m\xe1ximo um funcion\xe1rio contratado."},{type:"heading",level:2,text:"Documentos e informa\xe7\xf5es necess\xe1rias",id:"documentos-necessarios"},{type:"list",items:["CPF e n\xfamero do t\xedtulo de eleitor (ou do recibo da \xfaltima declara\xe7\xe3o de Imposto de Renda, se n\xe3o votou na \xfaltima elei\xe7\xe3o).","Endere\xe7o residencial e comercial (pode ser o mesmo, inclusive resid\xeancia).","E-mail e telefone para contato.","Defini\xe7\xe3o da atividade principal e, se for o caso, atividades secund\xe1rias dentro da lista permitida para MEI."]},{type:"heading",level:2,text:"Passo a passo da abertura",id:"passo-a-passo"},{type:"list",ordered:!0,items:["Acesse o Portal do Empreendedor (gov.br) e escolha a op\xe7\xe3o de formaliza\xe7\xe3o como MEI.","Informe seus dados pessoais e o endere\xe7o onde a atividade ser\xe1 exercida.","Escolha a atividade principal (CNAE) e, se aplic\xe1vel, at\xe9 15 atividades secund\xe1rias dentro da lista permitida.","Confira todos os dados informados e confirme a solicita\xe7\xe3o.","Baixe o Certificado da Condi\xe7\xe3o de Microempreendedor Individual (CCMEI), que j\xe1 sai com o CNPJ."]},{type:"callout",title:"Aten\xe7\xe3o na escolha da atividade",text:"Nem toda atividade profissional pode ser MEI — algumas exigem outro tipo de enquadramento, geralmente por envolverem regula\xe7\xe3o profissional espec\xedfica (como algumas atividades de sa\xfade ou jur\xeddicas). Antes de escolher, vale conferir se a atividade desejada est\xe1 na lista de ocupa\xe7\xf5es permitidas."},{type:"heading",level:2,text:"O que fazer logo depois de abrir o MEI",id:"depois-de-abrir"},{type:"list",items:["Guardar o CCMEI — \xe9 o documento que comprova o CNPJ e substitui o cart\xe3o CNPJ tradicional.","Verificar se \xe9 preciso Inscri\xe7\xe3o Municipal ou Estadual, dependendo da atividade e do munic\xedpio.","Organizar como e onde emitir nota fiscal, caso a atividade exija (venda para empresas ou \xf3rg\xe3os p\xfablicos, por exemplo).","Anotar o vencimento do DAS (todo dia 20) e programar o pagamento mensal.","Guardar um controle simples de receitas, mesmo informal, para a Declara\xe7\xe3o Anual do MEI."]},{type:"heading",level:2,text:"Vale abrir sozinho ou com ajuda de um contador?",id:"abrir-sozinho-ou-com-contador"},{type:"paragraph",text:"A abertura em si pode ser feita sozinho, sem custo. Mas contar com um contador desde o in\xedcio ajuda a escolher a atividade certa (evitando ter que corrigir depois), entender rapidamente as obriga\xe7\xf5es mensais e anuais, e j\xe1 deixar organizado o caminho para migrar de enquadramento no futuro, se o neg\xf3cio crescer al\xe9m do limite do MEI."}],faq:[{question:"Quanto custa abrir um MEI?",answer:"A abertura do MEI \xe9 100% gratuita, feita diretamente pelo Portal do Empreendedor. N\xe3o \xe9 necess\xe1rio pagar taxas de registro nem contratar ningu\xe9m para formalizar — o processo pode ser feito sozinho, em poucos minutos."},{question:"Posso ser MEI e ter carteira assinada ao mesmo tempo?",answer:"Sim, \xe9 permitido ser MEI e, ao mesmo tempo, ter um emprego CLT. As duas atividades s\xe3o independentes — o importante \xe9 que o faturamento do MEI respeite o limite anual da categoria."},{question:"Em quanto tempo o CNPJ do MEI fica pronto?",answer:"Na grande maioria dos casos, o CNPJ \xe9 emitido imediatamente ap\xf3s a confirma\xe7\xe3o dos dados no Portal do Empreendedor, e o CCMEI j\xe1 pode ser baixado na hora."}],relatedTool:{title:"Abrir meu MEI",href:"/abrir-cnpj",description:"Tire d\xfavidas sobre qual atividade escolher e o que organizar depois de abrir o MEI."},relatedSlugs:["o-que-e-das-mei-como-pagar","como-emitir-nota-fiscal-mei","quanto-custa-um-contador-para-mei"]},{slug:"como-emitir-nota-fiscal-mei",title:"Como emitir nota fiscal sendo MEI",metaTitle:"Como emitir nota fiscal MEI (passo a passo)",metaDescription:"Entenda quando o MEI precisa emitir nota fiscal, como fazer isso de gra\xe7a pelo Emissor Nacional e o que guardar depois.",excerpt:"Nem todo MEI precisa emitir nota fiscal o tempo todo — mas saber quando \xe9 obrigat\xf3rio evita problema com cliente e com a Receita. Veja como funciona.",pillar:"mei",coverImage:"/blog/covers/como-emitir-nota-fiscal-mei.jpg",coverImageAlt:"M\xe3os operando uma impressora port\xe1til de recibos",publishedAt:"2026-01-28",updatedAt:"2026-01-28",readingTimeMinutes:6,sections:[{type:"paragraph",text:"A emiss\xe3o de nota fiscal costuma ser uma das d\xfavidas mais recorrentes de quem \xe9 MEI — principalmente porque a obrigatoriedade muda dependendo de quem \xe9 o cliente. Entender essa regra evita tanto o transtorno de emitir nota sem precisar quanto o risco de deixar de emitir quando era obrigat\xf3rio."},{type:"heading",level:2,text:"Quando o MEI \xe9 obrigado a emitir nota fiscal",id:"quando-e-obrigatorio"},{type:"paragraph",text:"A regra pr\xe1tica \xe9 simples: sempre que a venda ou o servi\xe7o for para uma empresa (pessoa jur\xeddica) ou \xf3rg\xe3o p\xfablico, a nota fiscal \xe9 obrigat\xf3ria. J\xe1 para vendas a pessoas f\xedsicas, a emiss\xe3o n\xe3o \xe9 obrigat\xf3ria por padr\xe3o — mas, se o cliente pedir a nota, o MEI \xe9 obrigado a emitir, garantindo o direito do consumidor previsto no C\xf3digo de Defesa do Consumidor."},{type:"list",items:["Venda ou servi\xe7o para outra empresa (CNPJ): nota fiscal obrigat\xf3ria.","Venda ou servi\xe7o para \xf3rg\xe3o p\xfablico: nota fiscal obrigat\xf3ria.","Venda ou servi\xe7o para pessoa f\xedsica: obrigat\xf3ria apenas se o cliente solicitar."]},{type:"heading",level:2,text:"Como emitir a nota fiscal de servi\xe7o (NFS-e)",id:"como-emitir-nfse"},{type:"paragraph",text:"Desde a padroniza\xe7\xe3o nacional, o MEI prestador de servi\xe7o emite a NFS-e pelo Emissor Nacional, dispon\xedvel gratuitamente no site oficial. O passo a passo b\xe1sico \xe9:"},{type:"list",ordered:!0,items:["Acessar o Emissor Nacional de NFS-e com o CNPJ do MEI.","Preencher os dados do tomador do servi\xe7o (cliente): nome ou raz\xe3o social, CPF ou CNPJ e endere\xe7o.","Descrever o servi\xe7o prestado e o valor cobrado.","Emitir a nota, que gera um n\xfamero e um arquivo em PDF e XML.","Enviar o PDF ao cliente e guardar o XML para controle."]},{type:"heading",level:2,text:"E se o MEI vende produto em vez de servi\xe7o?",id:"mei-vende-produto"},{type:"paragraph",text:"Nesse caso, a nota \xe9 a NF-e (nota fiscal eletr\xf4nica de produto), emitida pela Secretaria da Fazenda do estado onde o MEI est\xe1 registrado, j\xe1 que envolve ICMS — diferente da nota de servi\xe7o, que \xe9 municipal. O processo de emiss\xe3o varia um pouco de estado para estado, mas segue a mesma l\xf3gica: dados do cliente, descri\xe7\xe3o dos itens e valores."},{type:"heading",level:2,text:"O que fazer com a nota depois de emitida",id:"o-que-fazer-depois"},{type:"list",items:["Guardar o arquivo XML por pelo menos 5 anos — \xe9 o documento que comprova a opera\xe7\xe3o perante a Receita.","Somar o total das notas emitidas no m\xeas, junto com as vendas sem nota, para o controle de faturamento mensal.","Usar esse total na Declara\xe7\xe3o Anual do MEI (DASN-SIMEI), feita uma vez por ano."]},{type:"callout",title:"A nota fiscal n\xe3o muda o valor do DAS",text:"Diferente de outros regimes, o valor do DAS do MEI \xe9 fixo e n\xe3o muda conforme a quantidade de notas emitidas. A nota fiscal serve para documentar a opera\xe7\xe3o e controlar se o faturamento est\xe1 dentro do limite anual permitido — n\xe3o gera cobran\xe7a adicional por nota."},{type:"heading",level:2,text:"Precisa de ajuda para organizar suas notas?",id:"precisa-de-ajuda"},{type:"paragraph",text:"Se a rotina de emitir e controlar notas fiscais est\xe1 tomando tempo demais, um contador especializado em MEI e pequenas empresas pode assumir essa parte — deixando voc\xea focado no que realmente importa: o seu neg\xf3cio."}],faq:[{question:"Emitir nota fiscal como MEI tem algum custo?",answer:"N\xe3o. A emiss\xe3o de NFS-e pelo Emissor Nacional \xe9 totalmente gratuita para o MEI. N\xe3o h\xe1 taxa por nota emitida."},{question:"O que acontece se eu n\xe3o emitir nota quando era obrigat\xf3rio?",answer:"Deixar de emitir nota fiscal quando obrigat\xf3rio pode gerar problemas com o cliente (que precisa da nota para lan\xe7ar a despesa) e, em fiscaliza\xe7\xf5es, pode ser interpretado como omiss\xe3o de faturamento — o que traz risco de autua\xe7\xe3o."},{question:"Preciso emitir nota mesmo recebendo por Pix ou dinheiro?",answer:"Sim, a forma de recebimento n\xe3o muda a obrigatoriedade da nota fiscal. O que determina se \xe9 obrigat\xf3rio \xe9 quem \xe9 o cliente (pessoa jur\xeddica ou f\xedsica) e se o cliente pessoa f\xedsica solicitou o documento."}],relatedTool:{title:"Abrir meu MEI",href:"/abrir-cnpj",description:"Tire d\xfavidas sobre emiss\xe3o de notas fiscais ou terceirize essa rotina para o seu MEI."},relatedSlugs:["o-que-e-das-mei-como-pagar","como-abrir-mei-passo-a-passo","quanto-custa-um-contador-para-mei"]},{slug:"cobrar-por-hora-ou-por-projeto",title:"Cobrar por hora ou por projeto fechado: como decidir",metaTitle:"Cobrar por hora ou projeto fechado? Como escolher",metaDescription:"Veja as vantagens e desvantagens de cobrar por hora versus por projeto fechado, e como escolher o melhor modelo para o seu tipo de servi\xe7o.",excerpt:"N\xe3o existe modelo certo ou errado — existe o modelo certo para cada tipo de servi\xe7o. Veja como decidir entre cobrar por hora ou por projeto fechado.",pillar:"precificacao",coverImage:"/blog/covers/cobrar-por-hora-ou-por-projeto.jpg",coverImageAlt:"Mesa de trabalho organizada com notebook e rel\xf3gio anal\xf3gico",publishedAt:"2026-01-30",updatedAt:"2026-01-30",readingTimeMinutes:6,sections:[{type:"paragraph",text:"Uma das primeiras decis\xf5es na hora de precificar um servi\xe7o \xe9: cobro por hora trabalhada ou fecho um valor \xfanico pelo projeto inteiro? Os dois modelos s\xe3o igualmente v\xe1lidos, mas funcionam melhor em situa\xe7\xf5es diferentes — e escolher o modelo errado para o tipo de trabalho \xe9 uma fonte comum de frustra\xe7\xe3o, tanto para quem presta quanto para quem contrata."},{type:"heading",level:2,text:"Cobrar por hora: quando faz sentido",id:"cobrar-por-hora"},{type:"paragraph",text:"Cobrar por hora funciona bem quando o escopo do trabalho \xe9 dif\xedcil de prever com precis\xe3o — situa\xe7\xf5es em que o tempo necess\xe1rio pode variar bastante dependendo de imprevistos, complexidade descoberta ao longo do caminho, ou mudan\xe7as frequentes de dire\xe7\xe3o pedidas pelo cliente."},{type:"list",items:["Consultoria cont\xednua, sem um entreg\xe1vel fixo definido de antem\xe3o.","Suporte t\xe9cnico ou manuten\xe7\xe3o sob demanda.","Projetos explorat\xf3rios, onde nem o cliente sabe exatamente o resultado final esperado."]},{type:"paragraph",text:"A vantagem: voc\xea \xe9 remunerado por todo o tempo dedicado, mesmo que o projeto tome mais tempo do que o esperado. A desvantagem: o cliente n\xe3o sabe o valor final at\xe9 o trabalho terminar, o que pode gerar desconforto ou desconfian\xe7a se n\xe3o houver transpar\xeancia sobre as horas."},{type:"heading",level:2,text:"Cobrar por projeto fechado: quando faz sentido",id:"cobrar-por-projeto-fechado"},{type:"paragraph",text:"O pre\xe7o fechado funciona melhor quando o escopo \xe9 claro e bem definido — o cliente sabe exatamente o que vai receber, e voc\xea consegue estimar com razo\xe1vel precis\xe3o quanto tempo e recurso o trabalho vai exigir."},{type:"list",items:["Servi\xe7os com entreg\xe1vel espec\xedfico: uma identidade visual, um contrato, uma pintura de ambiente.","Trabalhos que voc\xea j\xe1 fez v\xe1rias vezes e sabe estimar bem o tempo necess\xe1rio.","Situa\xe7\xf5es em que o cliente valoriza previsibilidade de custo mais do que flexibilidade de escopo."]},{type:"paragraph",text:"A vantagem: o cliente sabe o valor total desde o in\xedcio, o que facilita a decis\xe3o de compra. A desvantagem: se o trabalho tomar mais tempo do que o estimado (por imprevisto ou por escopo mal definido), esse tempo extra sai do seu bolso, n\xe3o do cliente."},{type:"callout",title:"Um risco do pre\xe7o fechado: o 'escopo que cresce'",text:"\xc9 comum, num contrato de pre\xe7o fechado, o cliente ir pedindo pequenos ajustes 'a mais' ao longo do caminho, achando que ainda est\xe1 dentro do combinado. Por isso, contratos com pre\xe7o fechado precisam descrever bem o que est\xe1 inclu\xeddo — e o que \xe9 considerado extra, cobrado \xe0 parte."},{type:"heading",level:2,text:"Um caminho do meio: pre\xe7o fechado com limite de revis\xf5es",id:"caminho-do-meio"},{type:"paragraph",text:"Muitos prestadores de servi\xe7o combinam os dois modelos: cobram um valor fechado pelo escopo principal, mas definem um n\xfamero de revis\xf5es ou ajustes inclu\xeddos — e cobram por hora (ou por pacote adicional) qualquer coisa al\xe9m disso. Esse modelo d\xe1 previsibilidade ao cliente e prote\xe7\xe3o a voc\xea contra o 'escopo que cresce'."},{type:"heading",level:2,text:"Na d\xfavida, calcule os dois e compare",id:"calcule-os-dois-e-compare"},{type:"paragraph",text:"Se n\xe3o tiver certeza de qual modelo escolher, vale estimar o tempo total do projeto, multiplicar pelo seu valor-hora, e comparar com o que cobraria fechado. Isso ajuda a verificar se o pre\xe7o fechado realmente compensa — ou se est\xe1, sem perceber, cobrando abaixo do que o tempo investido vale."},{type:"paragraph",text:"A Calculadora de Precifica\xe7\xe3o da Tropa ajuda nessa conta: voc\xea informa seus custos, o valor do seu tempo e a margem que quer, e v\xea o pre\xe7o sugerido — seja para um projeto fechado ou para calcular quanto vale a sua hora de trabalho."}],faq:[{question:"Posso cobrar por hora e ainda assim dar um valor estimado ao cliente?",answer:"Sim, e \xe9 recomendado. Mesmo cobrando por hora, \xe9 poss\xedvel (e saud\xe1vel) dar uma faixa estimada de horas e valor total ao cliente, com base em projetos parecidos anteriores — isso reduz a sensa\xe7\xe3o de imprevisibilidade sem abrir m\xe3o da flexibilidade do modelo."},{question:"Como sei quanto vale a minha hora de trabalho?",answer:"Uma forma pr\xe1tica: defina quanto quer ganhar por m\xeas, divida pelos dias que trabalha e pelas horas \xfateis de cada dia. Isso d\xe1 um valor-hora de refer\xeancia, que pode ser ajustado conforme a complexidade de cada tipo de servi\xe7o."}],relatedTool:{title:"Calculadora de Precifica\xe7\xe3o",href:"/ferramentas/calculadora-precificacao",description:"Informe seus custos, seu tempo e a margem que voc\xea quer — o pre\xe7o sugerido aparece na hora."},relatedSlugs:["como-calcular-preco-de-servico","o-que-nao-pode-faltar-contrato-prestacao-servico"]},{slug:"o-que-e-aviso-previo-como-funciona",title:"O que \xe9 aviso pr\xe9vio e como ele funciona na pr\xe1tica",metaTitle:"Aviso pr\xe9vio: o que \xe9, tipos e como calcular",metaDescription:"Entenda o que \xe9 aviso pr\xe9vio, a diferen\xe7a entre trabalhado e indenizado, e como ele varia conforme o tempo de casa do funcion\xe1rio.",excerpt:"O aviso pr\xe9vio \xe9 uma das partes mais confusas da rescis\xe3o — porque muda de acordo com quem pede o desligamento e quanto tempo de casa a pessoa tem. Veja como funciona.",pillar:"rescisao",coverImage:"/blog/covers/o-que-e-aviso-previo-como-funciona.jpg",coverImageAlt:"Mulher planejando a agenda em um calend\xe1rio de mesa",publishedAt:"2026-02-02",updatedAt:"2026-02-02",readingTimeMinutes:6,sections:[{type:"paragraph",text:"O aviso pr\xe9vio existe para dar tempo de ajuste para as duas partes de um contrato de trabalho: a empresa se organizar para substituir a pessoa, ou o funcion\xe1rio se organizar para buscar uma nova oportunidade. Na pr\xe1tica, por\xe9m, \xe9 uma das partes da rescis\xe3o que mais gera d\xfavida — porque muda de formato dependendo de quem tomou a iniciativa de encerrar o contrato."},{type:"heading",level:2,text:"Aviso pr\xe9vio trabalhado x indenizado",id:"trabalhado-x-indenizado"},{type:"paragraph",text:"Existem duas formas do aviso pr\xe9vio acontecer:"},{type:"list",items:["Trabalhado — o funcion\xe1rio continua trabalhando normalmente durante o per\xedodo do aviso (geralmente 30 dias), recebendo o sal\xe1rio normal desse per\xedodo.","Indenizado — a empresa dispensa o funcion\xe1rio de cumprir o per\xedodo, mas paga o valor correspondente como se ele tivesse trabalhado. O funcion\xe1rio j\xe1 sai da empresa, mas recebe o valor equivalente."]},{type:"heading",level:2,text:"Quem decide se o aviso \xe9 trabalhado ou indenizado",id:"quem-decide"},{type:"paragraph",text:"Na demiss\xe3o sem justa causa, a decis\xe3o \xe9 da empresa: ela pode optar por manter o funcion\xe1rio trabalhando durante o aviso ou dispens\xe1-lo do cumprimento, pagando o valor de forma indenizada. J\xe1 no pedido de demiss\xe3o, a regra \xe9 diferente: o funcion\xe1rio deve cumprir os 30 dias trabalhados, a n\xe3o ser que a empresa o dispense dessa exig\xeancia."},{type:"heading",level:2,text:"O aviso pr\xe9vio cresce com o tempo de casa",id:"aviso-previo-cresce-com-tempo-de-casa"},{type:"paragraph",text:"O per\xedodo padr\xe3o de aviso pr\xe9vio \xe9 de 30 dias, mas ele aumenta 3 dias para cada ano completo de trabalho na mesma empresa, at\xe9 o limite de 90 dias. Ou seja, quanto mais tempo de casa, maior o aviso pr\xe9vio a que o funcion\xe1rio tem direito."},{type:"table",headers:["Tempo de casa","Dias de aviso pr\xe9vio"],rows:[["At\xe9 1 ano","30 dias"],["2 anos completos","33 dias"],["5 anos completos","45 dias"],["10 anos completos ou mais","60 dias"],["20 anos completos","90 dias (limite m\xe1ximo)"]]},{type:"heading",level:2,text:"Aviso pr\xe9vio no aviso trabalhado: redu\xe7\xe3o da jornada",id:"reducao-da-jornada"},{type:"paragraph",text:"Quando o aviso \xe9 trabalhado, o funcion\xe1rio tem direito a uma redu\xe7\xe3o na jornada durante esse per\xedodo — 2 horas por dia a menos, ou a op\xe7\xe3o de faltar os \xfaltimos 7 dias corridos do aviso, sem preju\xedzo do sal\xe1rio. Isso serve justamente para dar tempo de buscar uma nova coloca\xe7\xe3o enquanto ainda est\xe1 empregado."},{type:"heading",level:2,text:"Aviso pr\xe9vio na rescis\xe3o por acordo",id:"aviso-previo-na-rescisao-por-acordo"},{type:"paragraph",text:"Na rescis\xe3o por acordo (quando empresa e funcion\xe1rio concordam em encerrar juntos), o aviso pr\xe9vio indenizado \xe9 pago pela metade, caso n\xe3o seja trabalhado. \xc9 uma das redu\xe7\xf5es que comp\xf5em o modelo de acordo, junto com a multa reduzida do FGTS."},{type:"heading",level:2,text:"Simule o valor da sua rescis\xe3o com aviso pr\xe9vio inclu\xeddo",id:"simule-com-aviso-previo"},{type:"paragraph",text:"O Simulador de Rescis\xe3o da Tropa j\xe1 considera o tipo de aviso pr\xe9vio de acordo com o tipo de desligamento escolhido, junto com as demais verbas — saldo de sal\xe1rio, 13\xba, f\xe9rias e multa do FGTS — para dar uma estimativa completa em segundos."}],faq:[{question:"O aviso pr\xe9vio \xe9 descontado do FGTS?",answer:"N\xe3o. O aviso pr\xe9vio, seja trabalhado ou indenizado, integra a remunera\xe7\xe3o para efeito de FGTS e demais verbas — inclusive conta como tempo de servi\xe7o para o c\xe1lculo de 13\xba e f\xe9rias proporcionais, mesmo quando indenizado."},{question:"Posso ser dispensado de cumprir o aviso pr\xe9vio quando pe\xe7o demiss\xe3o?",answer:"Sim, mas depende da empresa concordar. Se a empresa dispensar o cumprimento, o funcion\xe1rio n\xe3o precisa trabalhar os 30 dias, mas tamb\xe9m n\xe3o recebe o valor correspondente de forma indenizada — diferente de quando \xe9 a empresa que demite."}],relatedTool:{title:"Simulador de Rescis\xe3o",href:"/ferramentas/simulador-rescisao",description:"Escolha o tipo de desligamento e veja uma estimativa das principais verbas, incluindo aviso pr\xe9vio."},relatedSlugs:["diferenca-demissao-sem-justa-causa-pedido-acordo","quanto-custa-funcionario-clt","como-calcular-decimo-terceiro-salario"]},{slug:"mei-pode-ter-funcionario",title:"MEI pode ter funcion\xe1rio? Regras e limites",metaTitle:"MEI pode ter funcion\xe1rio? Veja as regras",metaDescription:"Entenda se o MEI pode contratar funcion\xe1rio CLT, quantos, quanto custa e o que muda nas obriga\xe7\xf5es mensais quando isso acontece.",excerpt:"O MEI pode ter um funcion\xe1rio — mas s\xf3 um, com regras espec\xedficas de sal\xe1rio e obriga\xe7\xf5es. Veja como funciona antes de contratar.",pillar:"contratacao",coverImage:"/blog/covers/mei-pode-ter-funcionario.jpg",coverImageAlt:"Tr\xeas pessoas colaborando em um projeto com notebook",publishedAt:"2026-02-04",updatedAt:"2026-02-04",readingTimeMinutes:5,sections:[{type:"paragraph",text:"Uma d\xfavida comum de quem est\xe1 crescendo como MEI \xe9 se d\xe1 para contratar algu\xe9m para ajudar. A resposta \xe9 sim, mas com uma regra importante que muita gente n\xe3o sabe: o MEI s\xf3 pode ter um \xfanico funcion\xe1rio registrado — n\xe3o dois, n\xe3o tr\xeas. Entender essa e outras regras evita problema com a Receita e com o funcion\xe1rio."},{type:"heading",level:2,text:"O limite de um funcion\xe1rio",id:"limite-de-um-funcionario"},{type:"paragraph",text:"O MEI pode ter, no m\xe1ximo, um funcion\xe1rio contratado sob o regime CLT. Se o neg\xf3cio crescer a ponto de precisar de mais de uma pessoa, \xe9 sinal de que est\xe1 na hora de migrar para outro enquadramento, como Microempresa (ME) do Simples Nacional."},{type:"heading",level:2,text:"Quanto pode ser pago para esse funcion\xe1rio",id:"quanto-pode-ser-pago"},{type:"paragraph",text:"O sal\xe1rio do funcion\xe1rio do MEI deve respeitar o piso de um sal\xe1rio m\xednimo nacional, ou o piso da categoria profissional (definido por conven\xe7\xe3o coletiva), o que for maior. N\xe3o h\xe1 um teto espec\xedfico al\xe9m disso — o MEI pode pagar mais do que o piso, se quiser e puder."},{type:"heading",level:2,text:"O que muda nas obriga\xe7\xf5es do MEI ao contratar",id:"o-que-muda-nas-obrigacoes"},{type:"list",items:["O DAS do MEI passa a incluir a contribui\xe7\xe3o previdenci\xe1ria patronal de 3% sobre o sal\xe1rio do funcion\xe1rio, somada ao valor fixo mensal j\xe1 pago.","Passa a ser obrigat\xf3rio recolher o FGTS (8% sobre o sal\xe1rio) mensalmente.","\xc9 preciso fazer o registro do funcion\xe1rio na carteira de trabalho digital e cumprir as obriga\xe7\xf5es trabalhistas b\xe1sicas (f\xe9rias, 13\xba, rescis\xe3o quando aplic\xe1vel).","A folha de pagamento e os encargos passam a exigir mais aten\xe7\xe3o — muitos MEIs contam com um contador nesse momento, mesmo que n\xe3o fosse necess\xe1rio antes."]},{type:"callout",title:"Vale a pena calcular antes de contratar",text:"Mesmo com o limite de um funcion\xe1rio e o piso do sal\xe1rio m\xednimo, os encargos (INSS patronal, FGTS, f\xe9rias e 13\xba proporcionais) somam um valor consider\xe1vel acima do sal\xe1rio combinado — vale estimar o custo total antes de decidir contratar."},{type:"heading",level:2,text:"MEI pode contratar como PJ em vez de CLT?",id:"mei-pode-contratar-pj"},{type:"paragraph",text:"Sim, o MEI pode contratar outros prestadores de servi\xe7o (PJ ou aut\xf4nomos) para ajudar em demandas espec\xedficas, sem que isso conte como o 'funcion\xe1rio CLT' permitido. A diferen\xe7a \xe9 que, nesse caso, n\xe3o existe v\xednculo empregat\xedcio — \xe9 uma rela\xe7\xe3o de presta\xe7\xe3o de servi\xe7o entre duas empresas ou entre empresa e aut\xf4nomo, sem os mesmos direitos trabalhistas."},{type:"heading",level:2,text:"Calcule o custo antes de contratar",id:"calcule-o-custo-antes"},{type:"paragraph",text:"O Simulador de Contrata\xe7\xe3o da Tropa ajuda a estimar o custo real de contratar — sal\xe1rio, encargos e benef\xedcios — antes de tomar a decis\xe3o, seja voc\xea MEI ou uma empresa maior."}],faq:[{question:"Se eu contratar um segundo funcion\xe1rio, o que acontece?",answer:"O MEI que ultrapassa o limite de um funcion\xe1rio precisa regularizar a situa\xe7\xe3o migrando para outro enquadramento, como Microempresa do Simples Nacional. Manter mais de um funcion\xe1rio registrado sob o MEI de forma irregular pode gerar problemas na fiscaliza\xe7\xe3o."},{question:"O funcion\xe1rio do MEI tem os mesmos direitos de um funcion\xe1rio CLT comum?",answer:"Sim. O funcion\xe1rio contratado por um MEI tem os mesmos direitos trabalhistas de qualquer funcion\xe1rio CLT: f\xe9rias, 13\xba sal\xe1rio, FGTS, aviso pr\xe9vio e demais garantias previstas na legisla\xe7\xe3o trabalhista."}],relatedTool:{title:"Simulador de Contrata\xe7\xe3o",href:"/ferramentas/simulador-contratacao",description:"Veja o custo estimado de contratar antes de tomar a decis\xe3o."},relatedSlugs:["quanto-custa-funcionario-clt","como-abrir-mei-passo-a-passo"]},{slug:"quanto-custa-um-contador-para-mei",title:"Quanto custa um contador para MEI (e quando vale a pena contratar)",metaTitle:"Quanto custa um contador para MEI? Veja quando vale a pena",metaDescription:"Entenda quanto custa a contabilidade para MEI, o que costuma estar incluso no valor mensal e em que momento contratar um contador realmente compensa.",excerpt:"Na maior parte do tempo, o MEI d\xe1 conta sozinho. Mas existem momentos em que contratar um contador passa a compensar de verdade. Veja quanto custa e quando vale a pena.",pillar:"mei",coverImage:"/blog/covers/quanto-custa-um-contador-para-mei.jpg",coverImageAlt:"Contador conversando com cliente sobre documentos financeiros",publishedAt:"2026-02-06",updatedAt:"2026-02-06",readingTimeMinutes:6,sections:[{type:"paragraph",text:"O MEI foi desenhado para ser simples o suficiente pra funcionar sem contador: o DAS \xe9 fixo, a declara\xe7\xe3o anual (DASN-SIMEI) \xe9 curta, e boa parte da rotina cabe no aplicativo MEI. Por isso, muita gente nem cogita contratar um contador — e, na maior parte do tempo, faz sentido n\xe3o contratar. O ponto \xe9 que existem momentos espec\xedficos em que isso muda, e vale entender quanto custa antes de precisar decidir com pressa."},{type:"heading",level:2,text:"MEI \xe9 obrigado a ter contador?",id:"mei-e-obrigado-a-ter-contador"},{type:"paragraph",text:"N\xe3o. O MEI \xe9 a \xfanica categoria empresarial no Brasil dispensada da obrigatoriedade de contador para cumprir suas obriga\xe7\xf5es b\xe1sicas — pagar o DAS e enviar a declara\xe7\xe3o anual. Isso foi uma escolha deliberada do legislador pra reduzir o custo de manter um MEI regular. O contador se torna \xfatil (\xe0s vezes necess\xe1rio na pr\xe1tica) quando a opera\xe7\xe3o cresce ou fica mais complexa — n\xe3o porque a lei exige, mas porque o risco de errar sozinho aumenta."},{type:"heading",level:2,text:"Quanto custa a contabilidade para MEI",id:"quanto-custa-a-contabilidade"},{type:"paragraph",text:"O valor varia bastante conforme a regi\xe3o, o volume de notas emitidas e o que est\xe1 incluso no plano, mas costuma ser um valor mensal fixo e acess\xedvel — bem mais barato do que a contabilidade de uma empresa de outro porte, j\xe1 que o volume de obriga\xe7\xf5es do MEI \xe9 bem menor. Em vez de comparar s\xf3 o pre\xe7o final, vale olhar o que est\xe1 incluso:"},{type:"list",items:["Emiss\xe3o de nota fiscal (ou orienta\xe7\xe3o de como emitir voc\xea mesmo).","Acompanhamento do DAS e alerta antes do vencimento.","Envio da declara\xe7\xe3o anual (DASN-SIMEI) dentro do prazo.","Suporte para d\xfavidas do dia a dia — sem cobran\xe7a extra por pergunta.","Orienta\xe7\xe3o sobre quando migrar de categoria, se o faturamento crescer."]},{type:"heading",level:2,text:"Quando contratar um contador passa a valer a pena",id:"quando-vale-a-pena-contratar"},{type:"list",items:["Voc\xea contratou (ou est\xe1 perto de contratar) um funcion\xe1rio — a folha de pagamento e os encargos exigem mais aten\xe7\xe3o.","Seu faturamento est\xe1 se aproximando do limite anual do MEI.","Voc\xea emite muitas notas fiscais por m\xeas e perde tempo fazendo isso manualmente.","Voc\xea j\xe1 recebeu alguma notifica\xe7\xe3o da Receita ou est\xe1 com o DAS atrasado.","Voc\xea est\xe1 pensando em migrar para Microempresa (ME) e n\xe3o sabe por onde come\xe7ar."]},{type:"callout",title:"O custo-benef\xedcio muda com o tamanho do neg\xf3cio",text:"Enquanto o MEI \xe9 pequeno e simples, o contador \xe9 opcional. Quando qualquer um dos pontos acima aparece, o custo mensal de um contador costuma ser bem menor do que o risco de uma multa, um DAS mal calculado ou uma migra\xe7\xe3o feita errado."},{type:"heading",level:2,text:"O que perguntar antes de contratar",id:"o-que-perguntar-antes-de-contratar"},{type:"paragraph",text:"Antes de fechar com um contador, vale confirmar tr\xeas coisas: se o valor mensal \xe9 fixo ou varia conforme o n\xfamero de notas emitidas, se o suporte \xe9 ilimitado ou cobrado por consulta, e se a emiss\xe3o de notas est\xe1 inclu\xedda ou \xe9 um servi\xe7o \xe0 parte. S\xe3o esses detalhes que fazem dois planos com o mesmo pre\xe7o anunciado terem experi\xeancias bem diferentes na pr\xe1tica."},{type:"heading",level:2,text:"Como funciona na Tropa",id:"como-funciona-na-tropa"},{type:"paragraph",text:"Os planos da Tropa foram pensados pra cobrir exatamente esses momentos: emiss\xe3o de nota fiscal, acompanhamento do DAS, envio de declara\xe7\xf5es, ferramentas ilimitadas de precifica\xe7\xe3o e contrata\xe7\xe3o, e suporte humanizado quando voc\xea precisar de uma resposta de verdade — sem esperar dias por retorno."}],faq:[{question:"MEI sem funcion\xe1rio e com pouco movimento precisa de contador?",answer:"Na maioria dos casos, n\xe3o \xe9 obrigat\xf3rio nem necess\xe1rio. O aplicativo MEI e o Portal do Simples Nacional d\xe3o conta das obriga\xe7\xf5es b\xe1sicas. O contador passa a fazer diferen\xe7a quando a opera\xe7\xe3o cresce em volume, complexidade ou risco."},{question:"Contratar contador \xe9 mais caro do que fazer sozinho?",answer:"Em valor mensal, sim — fazer sozinho \xe9 gratuito. Mas o c\xe1lculo relevante n\xe3o \xe9 s\xf3 o custo do contador: \xe9 o custo do contador comparado ao tempo perdido, ao risco de erro e \xe0s multas evitadas quando a situa\xe7\xe3o j\xe1 n\xe3o \xe9 t\xe3o simples."},{question:"D\xe1 pra trocar de plano conforme o neg\xf3cio cresce?",answer:"Sim. O ideal \xe9 come\xe7ar com o plano que cobre suas necessidades atuais e migrar quando o neg\xf3cio crescer — por exemplo, ao contratar o primeiro funcion\xe1rio ou ao se aproximar do limite de faturamento do MEI."}],relatedTool:{title:"Ver planos da Tropa",href:"/#planos",description:"Compare os planos e veja o que est\xe1 incluso em cada um, do MEI at\xe9 a empresa com funcion\xe1rios."},relatedSlugs:["como-trocar-de-contador","mei-ou-me-quando-migrar","o-que-e-das-mei-como-pagar"]},{slug:"como-trocar-de-contador",title:"Como trocar de contador sem dor de cabe\xe7a (passo a passo)",metaTitle:"Como trocar de contador: passo a passo sem burocracia",metaDescription:"Veja o passo a passo para trocar de contador com seguran\xe7a: documentos, procura\xe7\xe3o no e-CAC, comunica\xe7\xe3o e como evitar problemas na transi\xe7\xe3o.",excerpt:"Trocar de contador parece mais complicado do que realmente \xe9. Veja o passo a passo pra migrar sem perder prazo, sem perder documento e sem dor de cabe\xe7a.",pillar:"mei",coverImage:"/blog/covers/como-trocar-de-contador.jpg",coverImageAlt:"Profissionais trocando documentos durante uma reuni\xe3o",publishedAt:"2026-02-09",updatedAt:"2026-02-09",readingTimeMinutes:6,sections:[{type:"paragraph",text:"Falta de atendimento, atraso em obriga\xe7\xf5es, pre\xe7o fora da realidade do neg\xf3cio ou simplesmente a sensa\xe7\xe3o de que ningu\xe9m do outro lado est\xe1 prestando aten\xe7\xe3o — os motivos pra trocar de contador s\xe3o variados, mas a hesita\xe7\xe3o \xe9 sempre a mesma: 'ser\xe1 que vai dar trabalho?'. Na pr\xe1tica, a troca \xe9 bem mais simples do que parece, desde que voc\xea siga a ordem certa."},{type:"heading",level:2,text:"Voc\xea pode trocar de contador a qualquer momento",id:"pode-trocar-a-qualquer-momento"},{type:"paragraph",text:"N\xe3o existe per\xedodo de fidelidade nem necessidade de justificar a troca. A rela\xe7\xe3o entre empresa (ou MEI) e contador \xe9 um servi\xe7o contratado, e voc\xea pode encerr\xe1-lo quando quiser — respeitando apenas o aviso combinado no contrato, se houver algum prazo formal definido. O importante \xe9 organizar a transi\xe7\xe3o pra n\xe3o deixar nenhuma obriga\xe7\xe3o sem respons\xe1vel no meio do caminho."},{type:"heading",level:2,text:"Passo a passo para trocar de contador",id:"passo-a-passo"},{type:"list",ordered:!0,items:["Escolha o novo contador antes de encerrar com o atual — nunca fique sem nenhum dos dois no meio do processo.","Pe\xe7a ao contador atual os documentos e acessos: XML das notas emitidas, folha de pagamento (se tiver funcion\xe1rio), balancetes e relat\xf3rios do per\xedodo.","Comunique o encerramento formalmente, de prefer\xeancia por escrito (e-mail), registrando a data de corte.","Transfira a procura\xe7\xe3o digital no e-CAC para o novo contador — sem isso, o novo respons\xe1vel n\xe3o consegue acessar suas informa\xe7\xf5es na Receita Federal.","Confirme que todas as obriga\xe7\xf5es da compet\xeancia atual (DAS, folha, declara\xe7\xf5es) est\xe3o em dia antes da transi\xe7\xe3o efetivamente acontecer."]},{type:"heading",level:2,text:"Documentos que voc\xea precisa migrar",id:"documentos-para-migrar"},{type:"list",items:["Certificado digital (se tiver) e senha do Portal do Simples Nacional.","XML de todas as notas fiscais emitidas nos \xfaltimos anos.","Guias de DAS pagas e eventuais parcelamentos em aberto.","Dados da folha de pagamento, se houver funcion\xe1rio registrado.","Declara\xe7\xf5es anuais j\xe1 enviadas (DASN-SIMEI ou equivalente)."]},{type:"callout",title:"O melhor momento pra trocar",text:"Sempre que poss\xedvel, feche a transi\xe7\xe3o logo ap\xf3s o encerramento de uma compet\xeancia (m\xeas) — assim nenhuma obriga\xe7\xe3o fica pela metade entre o contador antigo e o novo, e a confus\xe3o sobre 'quem cuidou de qu\xea' desaparece."},{type:"heading",level:2,text:"Quanto tempo leva a transi\xe7\xe3o",id:"quanto-tempo-leva"},{type:"paragraph",text:"Na maioria dos casos, entre alguns dias e duas semanas — o tempo necess\xe1rio pra reunir os documentos, transferir a procura\xe7\xe3o no e-CAC e o novo contador revisar a situa\xe7\xe3o atual antes de assumir. Neg\xf3cios mais simples, como um MEI sem funcion\xe1rio, costumam migrar mais r\xe1pido do que empresas com folha de pagamento e hist\xf3rico fiscal mais longo."},{type:"heading",level:2,text:"Erros comuns na troca de contador",id:"erros-comuns"},{type:"list",items:["Encerrar com o contador atual antes de ter o pr\xf3ximo confirmado.","Esquecer de transferir a procura\xe7\xe3o digital no e-CAC.","Perder o acesso \xe0s senhas do Portal do Simples Nacional ou do certificado digital.","Trocar no meio de uma compet\xeancia, deixando obriga\xe7\xf5es sem respons\xe1vel claro."]}],faq:[{question:"Preciso avisar a Receita Federal quando troco de contador?",answer:"N\xe3o existe um aviso formal obrigat\xf3rio \xe0 Receita — o que precisa acontecer \xe9 a atualiza\xe7\xe3o da procura\xe7\xe3o digital no e-CAC, transferindo o acesso do contador anterior para o novo respons\xe1vel."},{question:"O contador antigo pode reter meus documentos?",answer:"N\xe3o. Os documentos fiscais e cont\xe1beis pertencem \xe0 empresa ou ao MEI, n\xe3o ao contador. Ele pode cobrar por eventuais servi\xe7os pendentes, mas n\xe3o pode se recusar a entregar os documentos e informa\xe7\xf5es da sua pr\xf3pria opera\xe7\xe3o."},{question:"Posso trocar de contador mesmo estando com obriga\xe7\xf5es atrasadas?",answer:"Sim, mas o ideal \xe9 deixar isso claro para o novo contador logo no in\xedcio, pra que ele j\xe1 entre sabendo o que precisa ser regularizado e em que prazo."}],relatedTool:{title:"Falar com um especialista",href:"https://wa.me/5521979080457",description:"Tire d\xfavidas sobre a transi\xe7\xe3o e veja como fica sua contabilidade com a Tropa."},relatedSlugs:["quanto-custa-um-contador-para-mei","o-que-e-das-mei-como-pagar","como-abrir-mei-passo-a-passo"]},{slug:"mei-ou-me-quando-migrar",title:"MEI ou Microempresa (ME): quando migrar e o que muda",metaTitle:"MEI ou ME: quando migrar e o que muda na pr\xe1tica",metaDescription:"Entenda a diferen\xe7a entre MEI e Microempresa (ME), os sinais de que \xe9 hora de migrar e o que muda em impostos, funcion\xe1rios e obriga\xe7\xf5es.",excerpt:"Todo MEI que cresce chega numa bifurca\xe7\xe3o: continuar como MEI ou virar Microempresa. Veja os sinais de que \xe9 hora de migrar e o que muda na pr\xe1tica.",pillar:"mei",coverImage:"/blog/covers/mei-ou-me-quando-migrar.jpg",coverImageAlt:"Colegas discutindo gr\xe1ficos de crescimento em um quadro branco",publishedAt:"2026-02-11",updatedAt:"2026-02-11",readingTimeMinutes:7,sections:[{type:"paragraph",text:"Quando o neg\xf3cio come\xe7a a crescer, o MEI que antes era suficiente come\xe7a a apertar em algum ponto: o limite de faturamento, o n\xfamero de funcion\xe1rios, o tipo de atividade. \xc9 nesse momento que aparece a d\xfavida sobre migrar para Microempresa (ME). Entender a diferen\xe7a entre as duas categorias ajuda a decidir com base em n\xfameros, n\xe3o em achismo."},{type:"heading",level:2,text:"A diferen\xe7a entre MEI e ME",id:"diferenca-entre-mei-e-me"},{type:"paragraph",text:"O MEI (Microempreendedor Individual) \xe9 um enquadramento simplificado dentro do Simples Nacional, criado para formalizar quem trabalha sozinho com faturamento baixo. A ME (Microempresa) \xe9 uma categoria maior dentro do pr\xf3prio Simples Nacional, com limite de faturamento bem mais alto, sem restri\xe7\xe3o r\xedgida de n\xfamero de funcion\xe1rios e com um leque maior de atividades permitidas — mas tamb\xe9m com uma rotina fiscal mais robusta."},{type:"table",headers:["Ponto","MEI","Microempresa (ME)"],rows:[["Limite de faturamento anual","Mais baixo, fixo por lei","Bem mais alto"],["Funcion\xe1rios","No m\xe1ximo 1","Sem limite r\xedgido"],["Tributa\xe7\xe3o","Valor fixo mensal (DAS)","Percentual sobre o faturamento (Simples Nacional)"],["Obriga\xe7\xf5es cont\xe1beis","Bem simplificadas","Exigem contabilidade regular"],["Emiss\xe3o de notas","Permitida, com limites da atividade","Mais ampla, conforme a atividade"]]},{type:"heading",level:2,text:"Sinais de que \xe9 hora de migrar",id:"sinais-de-que-e-hora-de-migrar"},{type:"list",items:["Seu faturamento j\xe1 ultrapassou (ou est\xe1 muito perto de ultrapassar) o limite anual do MEI.","Voc\xea precisa contratar mais de um funcion\xe1rio.","Voc\xea quer exercer uma atividade que n\xe3o est\xe1 na lista permitida para MEI.","Voc\xea precisa ter s\xf3cio, o que o MEI n\xe3o permite.","Seu neg\xf3cio j\xe1 lida com um volume de notas e clientes que pede uma estrutura cont\xe1bil mais completa."]},{type:"heading",level:2,text:"O que acontece se ultrapassar o limite sem migrar",id:"o-que-acontece-se-ultrapassar-sem-migrar"},{type:"paragraph",text:"Ultrapassar o limite de faturamento do MEI n\xe3o gera puni\xe7\xe3o autom\xe1tica, mas obriga a um processo de desenquadramento — a sa\xedda do regime de MEI e a migra\xe7\xe3o para o Simples Nacional como ME, com efeitos que podem ser retroativos ao m\xeas em que o limite foi ultrapassado. Dependendo do quanto excedeu, pode haver c\xe1lculo de impostos sobre a diferen\xe7a, o que torna a situa\xe7\xe3o mais cara do que se a migra\xe7\xe3o tivesse sido feita de forma planejada."},{type:"callout",title:"Migrar antes costuma sair mais barato",text:"Migrar de forma planejada, antes de estourar o limite, evita c\xe1lculo retroativo de impostos e d\xe1 tempo de organizar a contabilidade da nova categoria com calma — em vez de resolver tudo sob press\xe3o de um prazo da Receita."},{type:"heading",level:2,text:"Como funciona a migra\xe7\xe3o na pr\xe1tica",id:"como-funciona-a-migracao"},{type:"paragraph",text:"A migra\xe7\xe3o passa por tr\xeas frentes: a comunica\xe7\xe3o de desenquadramento do MEI (feita pelo pr\xf3prio empreendedor ou pelo contador), a op\xe7\xe3o formal pelo Simples Nacional como ME, e o ajuste da contabilidade — que passa a exigir escritura\xe7\xe3o regular, j\xe1 que a ME n\xe3o tem a mesma dispensa cont\xe1bil simplificada do MEI. \xc9 nesse ponto que ter um contador acompanhando deixa de ser opcional na pr\xe1tica, mesmo sem ser uma exig\xeancia do MEI original."},{type:"heading",level:2,text:"Vale a pena migrar antes de ser obrigado?",id:"vale-a-pena-migrar-antes"},{type:"paragraph",text:"Se os sinais de crescimento j\xe1 apareceram — mais de um funcion\xe1rio necess\xe1rio, faturamento subindo m\xeas a m\xeas, necessidade de s\xf3cio — migrar de forma planejada tende a ser mais barato e menos estressante do que esperar o limite estourar. O primeiro passo pr\xe1tico costuma ser entender o custo real de ter mais funcion\xe1rios, j\xe1 que \xe9 o gatilho mais comum para a migra\xe7\xe3o."}],faq:[{question:"Migrar de MEI para ME \xe9 definitivo?",answer:"Sim, uma vez desenquadrado do MEI, o retorno para essa categoria n\xe3o \xe9 autom\xe1tico — \xe9 preciso reabrir como MEI depois, caso o faturamento volte a se enquadrar nos limites, respeitando as regras vigentes na \xe9poca."},{question:"Preciso de contador para migrar de MEI para ME?",answer:"N\xe3o \xe9 uma exig\xeancia legal para iniciar o processo de desenquadramento, mas a ME exige contabilidade regular a partir da migra\xe7\xe3o, o que na pr\xe1tica torna o acompanhamento de um contador necess\xe1rio para manter tudo em dia."},{question:"O que acontece com as notas fiscais j\xe1 emitidas como MEI depois da migra\xe7\xe3o?",answer:"Elas continuam v\xe1lidas e fazem parte do seu hist\xf3rico fiscal. A migra\xe7\xe3o muda o enquadramento da\xed em diante — n\xe3o invalida o que j\xe1 foi emitido antes."}],relatedTool:{title:"Simulador de Contrata\xe7\xe3o",href:"/ferramentas/simulador-contratacao",description:"Se a migra\xe7\xe3o \xe9 por causa de funcion\xe1rios, veja o custo estimado de contratar antes de decidir."},relatedSlugs:["mei-pode-ter-funcionario","quanto-custa-um-contador-para-mei","como-abrir-mei-passo-a-passo"]},{slug:"como-calcular-decimo-terceiro-salario",title:"Como calcular o 13\xba sal\xe1rio passo a passo",metaTitle:"Como calcular o 13\xba sal\xe1rio (passo a passo com exemplo)",metaDescription:"Aprenda a calcular o 13\xba sal\xe1rio passo a passo, incluindo a primeira e a segunda parcela, descontos e o que muda em caso de desligamento.",excerpt:"O 13\xba sal\xe1rio parece simples at\xe9 a hora de calcular direito — primeira parcela, segunda parcela, descontos. Veja o passo a passo com exemplo pr\xe1tico.",pillar:"contratacao",coverImage:"/blog/covers/como-calcular-decimo-terceiro-salario.jpg",coverImageAlt:"Mulher sorrindo segurando dinheiro e um envelope",publishedAt:"2026-02-13",updatedAt:"2026-02-13",readingTimeMinutes:6,sections:[{type:"paragraph",text:"O 13\xba sal\xe1rio \xe9 um direito garantido a todo funcion\xe1rio CLT, mas o c\xe1lculo tem mais detalhes do que parece \xe0 primeira vista — principalmente na hora de dividir entre a primeira e a segunda parcela, e de aplicar os descontos corretos. Veja o passo a passo pra calcular sem erro."},{type:"heading",level:2,text:"Como funciona o 13\xba sal\xe1rio",id:"como-funciona-o-13o"},{type:"paragraph",text:"Todo funcion\xe1rio que trabalhou pelo menos 15 dias em um m\xeas tem direito a 1/12 do sal\xe1rio referente \xe0quele m\xeas no c\xe1lculo do 13\xba. O pagamento \xe9 feito obrigatoriamente em duas parcelas: a primeira at\xe9 30 de novembro, e a segunda at\xe9 20 de dezembro (essas datas s\xe3o fixas por lei, independente do ano). O 13\xba pode ser antecipado junto com as f\xe9rias, se o funcion\xe1rio solicitar."},{type:"heading",level:2,text:"A f\xf3rmula do c\xe1lculo",id:"formula-do-calculo"},{type:"paragraph",text:"O c\xe1lculo b\xe1sico \xe9: (sal\xe1rio bruto \xf7 12) \xd7 n\xfamero de meses trabalhados no ano. Quem trabalhou o ano inteiro recebe o equivalente a um sal\xe1rio integral de 13\xba; quem trabalhou parte do ano recebe proporcionalmente aos meses trabalhados."},{type:"callout",title:"Exemplo pr\xe1tico",text:"Um funcion\xe1rio com sal\xe1rio de R$3.000 que trabalhou os 12 meses do ano tem direito a R$3.000 de 13\xba integral. Se tivesse trabalhado apenas 8 meses, o c\xe1lculo seria (R$3.000 \xf7 12) \xd7 8 = R$2.000."},{type:"heading",level:2,text:"Primeira parcela vs segunda parcela",id:"primeira-vs-segunda-parcela"},{type:"paragraph",text:"A primeira parcela corresponde a 50% do valor bruto do 13\xba, paga sem nenhum desconto. A segunda parcela corresponde ao valor total do 13\xba, descontada a primeira parcela j\xe1 paga — e \xe9 sobre essa segunda parcela que incidem os descontos de INSS e, quando aplic\xe1vel, de Imposto de Renda, calculados sobre o valor cheio do 13\xba (n\xe3o apenas sobre a segunda parcela isoladamente)."},{type:"heading",level:2,text:"Descontos que incidem sobre o 13\xba",id:"descontos-sobre-o-13o"},{type:"list",items:["INSS — calculado sobre o valor total do 13\xba, seguindo a mesma tabela progressiva usada no sal\xe1rio mensal.","Imposto de Renda — incide apenas se o valor do 13\xba (j\xe1 descontado o INSS) ultrapassar a faixa de isen\xe7\xe3o da tabela do IR, e \xe9 retido somente na segunda parcela."]},{type:"heading",level:2,text:"O que acontece com o 13\xba em caso de demiss\xe3o",id:"13o-em-caso-de-demissao"},{type:"paragraph",text:"Quando o contrato \xe9 encerrado antes do fim do ano, o 13\xba proporcional aos meses trabalhados entra como uma das verbas da rescis\xe3o — e o tratamento varia conforme o tipo de desligamento (sem justa causa, pedido de demiss\xe3o ou acordo)."},{type:"heading",level:2,text:"Calcule o custo de um funcion\xe1rio incluindo o 13\xba",id:"calcule-o-custo-incluindo-13o"},{type:"paragraph",text:"Se voc\xea est\xe1 avaliando contratar, o 13\xba \xe9 um dos encargos que precisa entrar na conta desde o in\xedcio — junto com f\xe9rias, FGTS e demais obriga\xe7\xf5es. O Simulador de Contrata\xe7\xe3o da Tropa j\xe1 inclui esses valores na estimativa de custo total."}],faq:[{question:"Quem trabalhou menos de 12 meses tem direito a 13\xba?",answer:"Sim, desde que tenha trabalhado pelo menos 15 dias em cada m\xeas considerado. O valor \xe9 proporcional: 1/12 do sal\xe1rio para cada m\xeas trabalhado dentro desse crit\xe9rio."},{question:"Aut\xf4nomo ou MEI tem direito a 13\xba sal\xe1rio?",answer:"N\xe3o. O 13\xba \xe9 um direito exclusivo de quem tem v\xednculo empregat\xedcio CLT. Aut\xf4nomos, MEIs e prestadores de servi\xe7o PJ n\xe3o t\xeam direito a essa verba, j\xe1 que n\xe3o h\xe1 rela\xe7\xe3o de emprego formal envolvida."},{question:"O 13\xba entra no c\xe1lculo do FGTS?",answer:"Sim. O valor pago a t\xedtulo de 13\xba sal\xe1rio tamb\xe9m sofre incid\xeancia de FGTS (8%), depositado pelo empregador junto com o restante da remunera\xe7\xe3o do per\xedodo."}],relatedTool:{title:"Simulador de Contrata\xe7\xe3o",href:"/ferramentas/simulador-contratacao",description:"Veja o custo total de um funcion\xe1rio, incluindo 13\xba, f\xe9rias e demais encargos."},relatedSlugs:["ferias-clt-como-funciona-o-calculo","quanto-custa-funcionario-clt","diferenca-demissao-sem-justa-causa-pedido-acordo"]},{slug:"ferias-clt-como-funciona-o-calculo",title:"F\xe9rias CLT: como funciona o c\xe1lculo (e o que \xe9 f\xe9rias em dobro)",metaTitle:"F\xe9rias CLT: como calcular (e o que s\xe3o f\xe9rias em dobro)",metaDescription:"Entenda como funciona o c\xe1lculo das f\xe9rias CLT, o adicional de um ter\xe7o, f\xe9rias proporcionais, abono pecuni\xe1rio e o que s\xe3o f\xe9rias em dobro.",excerpt:"F\xe9rias CLT t\xeam mais regras do que parece: adicional de 1/3, proporcionalidade, abono pecuni\xe1rio e o temido pagamento em dobro. Veja como funciona cada parte.",pillar:"contratacao",coverImage:"/blog/covers/ferias-clt-como-funciona-o-calculo.jpg",coverImageAlt:"Mulher relaxando com um caf\xe9 em uma cadeira na praia",publishedAt:"2026-02-16",updatedAt:"2026-02-16",readingTimeMinutes:6,sections:[{type:"paragraph",text:"Todo funcion\xe1rio CLT tem direito a 30 dias de f\xe9rias por ano, mas o valor pago e as regras em volta disso — adicional, proporcionalidade, venda de dias, pagamento em dobro — costumam gerar mais d\xfavida do que o pr\xf3prio per\xedodo de descanso. Veja como cada parte funciona."},{type:"heading",level:2,text:"Quando o funcion\xe1rio tem direito a f\xe9rias",id:"quando-tem-direito-a-ferias"},{type:"paragraph",text:"O direito \xe0s f\xe9rias nasce ap\xf3s 12 meses de trabalho, chamado de per\xedodo aquisitivo. A partir da\xed, a empresa tem os 12 meses seguintes (per\xedodo concessivo) para conceder os 30 dias de descanso. Ou seja: entre o in\xedcio do direito e o prazo final para tirar as f\xe9rias, o funcion\xe1rio e a empresa t\xeam at\xe9 dois anos de janela — mas deixar para a \xfaltima hora \xe9 arriscado, como voc\xea vai ver mais adiante."},{type:"heading",level:2,text:"Como calcular o valor das f\xe9rias",id:"como-calcular-o-valor"},{type:"paragraph",text:"O valor das f\xe9rias \xe9 o sal\xe1rio normal do funcion\xe1rio acrescido de um ter\xe7o constitucional — um adicional garantido pela Constitui\xe7\xe3o, pago junto com as f\xe9rias. A f\xf3rmula \xe9 simples: sal\xe1rio + (sal\xe1rio \xf7 3)."},{type:"callout",title:"Exemplo pr\xe1tico",text:"Um funcion\xe1rio com sal\xe1rio de R$3.000 recebe, nas f\xe9rias, R$3.000 + R$1.000 (um ter\xe7o) = R$4.000 no total."},{type:"heading",level:2,text:"F\xe9rias proporcionais",id:"ferias-proporcionais"},{type:"paragraph",text:"Quando o funcion\xe1rio \xe9 desligado antes de completar um novo per\xedodo aquisitivo de 12 meses, ele tem direito \xe0s f\xe9rias proporcionais aos meses trabalhados — calculadas na base de 1/12 do valor das f\xe9rias integrais para cada m\xeas completo trabalhado, tamb\xe9m com o adicional de um ter\xe7o."},{type:"heading",level:2,text:"Abono pecuni\xe1rio: vender parte das f\xe9rias",id:"abono-pecuniario"},{type:"paragraph",text:"O funcion\xe1rio pode optar por vender at\xe9 1/3 dos dias de f\xe9rias (10 dos 30 dias) para a empresa, recebendo o valor correspondente em dinheiro em vez de descansar esses dias. Essa op\xe7\xe3o precisa ser comunicada at\xe9 15 dias antes do fim do per\xedodo aquisitivo, e cabe ao funcion\xe1rio decidir — n\xe3o \xe0 empresa impor."},{type:"heading",level:2,text:"O que s\xe3o f\xe9rias em dobro (e quando a empresa \xe9 obrigada a pagar)",id:"ferias-em-dobro"},{type:"paragraph",text:"Se a empresa n\xe3o conceder as f\xe9rias dentro do per\xedodo concessivo (os 12 meses ap\xf3s o funcion\xe1rio completar o direito), ela \xe9 obrigada a pagar o valor das f\xe9rias em dobro — ou seja, o dobro do sal\xe1rio mais o adicional de um ter\xe7o, tamb\xe9m dobrado. \xc9 uma penalidade prevista em lei justamente para evitar que f\xe9rias fiquem acumulando indefinidamente sem serem tiradas."},{type:"table",headers:["Situa\xe7\xe3o","O que \xe9 pago"],rows:[["F\xe9rias tiradas dentro do prazo","Sal\xe1rio + 1/3 constitucional"],["F\xe9rias proporcionais (desligamento)","1/12 por m\xeas trabalhado + 1/3"],["F\xe9rias n\xe3o concedidas no prazo","Valor em dobro (sal\xe1rio + 1/3, tudo em dobro)"]]},{type:"heading",level:2,text:"Simule o custo de f\xe9rias de um funcion\xe1rio",id:"simule-o-custo"},{type:"paragraph",text:"Assim como o 13\xba, o custo de f\xe9rias precisa entrar na conta desde a decis\xe3o de contratar — n\xe3o s\xf3 no m\xeas em que elas acontecem. O Simulador de Contrata\xe7\xe3o da Tropa j\xe1 estima esse valor junto com os demais encargos."}],faq:[{question:"A empresa pode obrigar o funcion\xe1rio a tirar f\xe9rias em um per\xedodo espec\xedfico?",answer:"Sim, cabe \xe0 empresa definir o per\xedodo das f\xe9rias dentro do prazo concessivo, respeitando algumas restri\xe7\xf5es legais (como n\xe3o iniciar f\xe9rias nos dois dias que antecedem um feriado ou descanso semanal). O funcion\xe1rio n\xe3o escolhe a data sozinho, mas pode negociar."},{question:"Funcion\xe1rio em f\xe9rias pode ser demitido?",answer:"A demiss\xe3o durante o per\xedodo de f\xe9rias n\xe3o \xe9 proibida por lei, mas a empresa precisa ter cuidado com a chamada estabilidade provis\xf3ria em outras situa\xe7\xf5es (como gestante), que s\xe3o independentes das f\xe9rias em si."},{question:"As f\xe9rias contam para o c\xe1lculo do FGTS?",answer:"Sim, o valor das f\xe9rias (incluindo o adicional de um ter\xe7o) sofre incid\xeancia de FGTS, que deve ser depositado pela empresa normalmente."}],relatedTool:{title:"Simulador de Contrata\xe7\xe3o",href:"/ferramentas/simulador-contratacao",description:"Veja o custo total de um funcion\xe1rio, incluindo f\xe9rias, 13\xba e demais encargos."},relatedSlugs:["como-calcular-decimo-terceiro-salario","quanto-custa-funcionario-clt","o-que-e-aviso-previo-como-funciona"]},{slug:"contrato-verbal-tem-validade",title:"Contrato verbal tem validade? Os riscos de prestar servi\xe7o sem contrato",metaTitle:"Contrato verbal tem validade jur\xeddica? Veja os riscos",metaDescription:"Entenda se o contrato verbal tem validade jur\xeddica no Brasil, quais os riscos de prestar servi\xe7o sem contrato escrito e como se proteger.",excerpt:"'Combinamos por WhatsApp' n\xe3o \xe9 a mesma coisa que ter um contrato. Veja se o contrato verbal tem validade e por que ele deixa voc\xea exposto quando algo d\xe1 errado.",pillar:"contratos",coverImage:"/blog/covers/contrato-verbal-tem-validade.jpg",coverImageAlt:"Duas pessoas apertando as m\xe3os em um escrit\xf3rio",publishedAt:"2026-02-18",updatedAt:"2026-02-18",readingTimeMinutes:6,sections:[{type:"paragraph",text:"Boa parte dos prestadores de servi\xe7o combina tudo por mensagem, liga pra fechar detalhes e come\xe7a a trabalhar sem nunca assinar nada. Funciona bem — at\xe9 o dia em que o cliente discorda do que foi combinado, atrasa o pagamento ou muda o escopo no meio do caminho. \xc9 a\xed que a pergunta aparece: um contrato verbal vale alguma coisa?"},{type:"heading",level:2,text:"Contrato verbal tem validade legal?",id:"contrato-verbal-tem-validade-legal"},{type:"paragraph",text:"Sim. No Brasil, o C\xf3digo Civil n\xe3o exige forma escrita para a maioria dos contratos de presta\xe7\xe3o de servi\xe7o — um acordo verbal, feito de boa-f\xe9, \xe9 juridicamente v\xe1lido e pode ser cobrado judicialmente se necess\xe1rio. O problema n\xe3o est\xe1 na validade em si, mas no que vem logo depois: provar o que foi combinado."},{type:"heading",level:2,text:"O problema n\xe3o \xe9 validade, \xe9 prova",id:"o-problema-e-a-prova"},{type:"paragraph",text:"Quando surge uma diverg\xeancia, quem alega algo precisa provar. Num contrato verbal, n\xe3o existe um documento \xfanico que descreva exatamente o que foi combinado — o que sobra s\xe3o fragmentos espalhados em conversas, e cada parte tende a lembrar (ou defender) uma vers\xe3o diferente do acordo original."},{type:"list",items:["Qual era o escopo exato do servi\xe7o combinado.","O prazo de entrega definido.","O valor e a forma de pagamento (\xe0 vista, parcelado, por etapa).","O que conta como 'servi\xe7o conclu\xeddo' aos olhos das duas partes.","Quem paga por retrabalho ou ajustes fora do combinado inicial."]},{type:"heading",level:2,text:"O que pode servir como prova, mesmo sem contrato formal",id:"o-que-pode-servir-como-prova"},{type:"paragraph",text:"Conversas de WhatsApp, e-mails trocados e comprovantes de pagamento podem ajudar a reconstruir o que foi combinado, e n\xe3o s\xe3o desprezados judicialmente. O problema \xe9 que s\xe3o provas fragmentadas e indiretas — muito mais fracas e trabalhosas de sustentar do que um \xfanico documento assinado por ambas as partes, que j\xe1 nasce descrevendo o acordo por completo."},{type:"heading",level:2,text:"Quando um contrato escrito \xe9 praticamente obrigat\xf3rio",id:"quando-e-praticamente-obrigatorio"},{type:"list",items:["Servi\xe7os de valor alto, onde uma diverg\xeancia custa caro pra qualquer lado.","Prazos longos ou presta\xe7\xe3o continuada (contratos mensais, assinaturas de servi\xe7o).","Projetos com escopo complexo, que podem mudar no meio do caminho.","Situa\xe7\xf5es que envolvem terceiros, subcontratados ou uma equipe."]},{type:"callout",title:"Contrato n\xe3o \xe9 sinal de desconfian\xe7a",text:"Um dos motivos mais comuns pra n\xe3o formalizar \xe9 o medo de 'parecer desconfiado' com o cliente. Na pr\xe1tica, \xe9 o contr\xe1rio: um contrato bem escrito protege as duas partes igualmente, e clientes profissionais costumam ver isso como sinal de organiza\xe7\xe3o, n\xe3o de desconfian\xe7a."},{type:"heading",level:2,text:"Como sair do contrato verbal sem perder o cliente",id:"como-sair-do-contrato-verbal"},{type:"paragraph",text:"Se voc\xea j\xe1 tem clientes recorrentes que nunca assinaram nada, a transi\xe7\xe3o pode ser simples: envie um contrato resumindo o que j\xe1 \xe9 praticado entre voc\xeas, deixando claro que \xe9 s\xf3 uma formaliza\xe7\xe3o do que j\xe1 funciona. Na maioria dos casos, o cliente assina sem resist\xeancia — porque n\xe3o muda nada do que j\xe1 foi combinado, s\xf3 documenta."},{type:"heading",level:2,text:"Gere um contrato em minutos",id:"gere-um-contrato-em-minutos"},{type:"paragraph",text:"N\xe3o precisa come\xe7ar do zero nem contratar um advogado pra ter um contrato b\xe1sico de presta\xe7\xe3o de servi\xe7o. O Gerador de Contrato da Tropa monta um contrato personalizado com escopo, prazo, valor e forma de pagamento, pronto pra revisar e assinar."}],faq:[{question:"Conversa de WhatsApp conta como contrato?",answer:"N\xe3o substitui um contrato formal, mas pode servir como prova complementar em caso de disputa. \xc9 uma evid\xeancia fraca comparada a um documento \xfanico assinado pelas duas partes, que descreve o acordo completo de forma clara."},{question:"Preciso de advogado para fazer um contrato simples de presta\xe7\xe3o de servi\xe7o?",answer:"Para a maioria dos servi\xe7os do dia a dia, um contrato bem estruturado — com escopo, prazo, valor e condi\xe7\xf5es de pagamento — j\xe1 cobre o essencial. Um advogado se torna importante em situa\xe7\xf5es espec\xedficas ou de maior complexidade jur\xeddica."},{question:"O contrato precisa ser assinado com certificado digital para valer?",answer:"N\xe3o necessariamente. Um contrato assinado fisicamente ou por uma plataforma de assinatura eletr\xf4nica simples j\xe1 tem validade — o certificado digital refor\xe7a a seguran\xe7a jur\xeddica, mas n\xe3o \xe9 o \xfanico caminho v\xe1lido."}],relatedTool:{title:"Gerador de Contrato",href:"/ferramentas/gerador-contrato",description:"Gere um contrato de presta\xe7\xe3o de servi\xe7o personalizado em poucos minutos, sem come\xe7ar do zero."},relatedSlugs:["o-que-nao-pode-faltar-contrato-prestacao-servico","o-que-fazer-quando-cliente-nao-paga","como-calcular-preco-de-servico"]}];function e(){return[...d].sort((a,b)=>a.publishedAt<b.publishedAt?1:-1)}function f(a){return e().slice(0,a)}function g(a){return d.find(b=>b.slug===a)}function h(a){return a.relatedSlugs.map(a=>g(a)).filter(a=>!!a)}}};